      add(cap, { ray: false, cast: false })
      // buttresses
      const count = Math.max(2, Math.round(segLen / 6))
      for (let i = 0; i < count; i++) {
        const t = (i + 0.5) / count
        const bx = horiz ? x - w / 2 + t * w : x
        const bz = horiz ? z : z - d / 2 + t * d
