  // ---------- crates / barrels / tires / pipes ----------
  const crateSpots = [
    [-13, -10, 1.4], [-11.4, -10, 0.9], [-13.6, -12.2, 1.1], [12, -25, 1.5],
    [13.8, -24.6, 1.0], [24, 3, 1.2], [25.5, 3.6, 0.8], [-27, 18, 1.4],
