    }
    for (let i = 0; i < 3; i++) {
      const lamp = box(0.55, 0.3, 0.8, lampMat, -0.9 + i * 0.9, 11.5, 0)
      g.add(lamp)
    }
    g.position.set(f.x, 0, f.z)
    add(g, { collide: true, ray: true })
    const dx = f.tx - f.x, dz = f.tz - f.z
    const dist = Math.hypot(dx, dz)
    const cone = new THREE.Mesh(new THREE.ConeGeometry(3.2, 16, 20, 1, true), coneMat)
    cone.position.set(f.x, 11.3 - 8, f.z)
    // orient cone -Y toward target
    const dir = new THREE.Vector3(dx, -10.8, dz).normalize()
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir)
    cone.quaternion.copy(q)
    cone.position.set(f.x + dx * 0.25, 6.3, f.z + dz * 0.25)
    scene.add(cone)
    const spot = new THREE.SpotLight(f.color, f.intensity, 48, 0.42, 0.75, 1.1)
    spot.position.set(f.x, 11.3, f.z)
    spot.target.position.set(f.tx, 0, f.tz)
    scene.add(spot, spot.target)
    flickerLights.push({ spot, cone, base: f.intensity, phase: rand(0, 20), rate: rand(0.6, 1.3) })
    const flair = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('flare'), color: 0xffd8a0, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false }))
    flair.scale.set(12, 12, 1)
    flair.position.set(f.x, 11.3, f.z)
    scene.add(flair)
    addCover(f.x + 1.6, f.z + 1.2)
  }

  // searchlight tower (rotating)
  const searchTower = new THREE.Group()
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const leg = box(0.22, 13, 0.22, MAT.metalDark, sx * 1.4, 6.5, sz * 1.4)
    searchTower.add(leg)
  }
  for (let i = 0; i < 3; i++) {
    const ring = box(3, 0.16, 3, MAT.metalDark, 0, 3 + i * 4, 0)
    searchTower.add(ring)
  }
  const cabin = box(3.6, 2.2, 3.6, MAT.metalDark, 0, 12.2, 0)
  searchTower.add(cabin)
  const roof = box(4.2, 0.16, 4.2, MAT.metalLight, 0, 13.4, 0)
  searchTower.add(roof)
  searchTower.position.set(-30, 0, -30)
  searchTower.rotation.y = 0.4
  add(searchTower, { collide: true })
  const searchSpot = new THREE.SpotLight(0xcfe6ff, 900, 100, 0.055, 0.35, 1.1)
  searchSpot.position.set(-30, 13.2, -30)
  const searchTarget = new THREE.Object3D()
  searchTarget.position.set(0, 0, 0)
  scene.add(searchSpot, searchTarget)
  searchSpot.target = searchTarget
  const searchCone = new THREE.Mesh(new THREE.ConeGeometry(2.5, 48, 16, 1, true), new THREE.MeshBasicMaterial({ color: 0xa8c8ee, transparent: true, opacity: 0.028, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }))
  scene.add(searchCone)
  const searchGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('glow'), color: 0x9fc4f0, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }))
  searchGlow.scale.set(3.2, 3.2, 1)
  searchGlow.position.set(-30, 13.4, -30)
  scene.add(searchGlow)
  const searchLight = { spot: searchSpot, cone: searchCone, target: searchTarget, angle: 0 }
  animated.push({ type: 'search', obj: searchLight })

  // ---------- watchtowers / antenna ----------
  function watchtower(x, z) {
    const g = new THREE.Group()
    for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
      g.add(box(0.24, 9.5, 0.24, MAT.metalDark, sx * 1.6, 4.75, sz * 1.6))
      const brace1 = box(0.14, 0.14, 3.7, MAT.metalDark, sx * 1.6, 3, 0); brace1.rotation.x = 0.74; g.add(brace1)
    }
    g.add(box(4.2, 0.2, 4.2, MAT.metalDark, 0, 9.2, 0))
    g.add(box(3.6, 0.9, 3.6, MAT.metalDark, 0, 9.8, 0))
    g.add(box(4.6, 0.15, 4.6, MAT.metalLight, 0, 10.5, 0))
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff2a16 }))
    lamp.position.set(0, 10.8, 0)
    g.add(lamp)
    const beam = new THREE.Mesh(new THREE.ConeGeometry(1.2, 6, 12, 1, true), new THREE.MeshBasicMaterial({ color: 0xff3a20, transparent: true, opacity: 0.05, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }))
    beam.position.y = 7.6; beam.rotation.x = Math.PI
    g.add(beam)
    g.position.set(x, 0, z)
    if (Math.abs(x) < 40) add(g, { collide: true, ray: true })
    else scene.add(g)
    beacons.push({ lamp, glow: null, phase: rand(0, 6) })
    return g
  }
  watchtower(-33, -33); watchtower(33, -33); watchtower(-33, 33); watchtower(33, 33)

  // antenna mast
  const mast = new THREE.Group()
  mast.add(cyl(0.09, 0.16, 24, MAT.metalDark, 0, 12, 0, 8))
  for (let i = 0; i < 5; i++) {
    const r = 1.4 - i * 0.22
    const ring = new THREE.Mesh(new THREE.TorusGeometry(r, 0.035, 4, 12), MAT.metalDark)
    ring.rotation.x = Math.PI / 2; ring.position.y = 6 + i * 4
    mast.add(ring)
  }
  for (let i = 0; i < 4; i++) {
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.09, 6, 5), new THREE.MeshBasicMaterial({ color: 0xff2a16 }))
    beacon.position.set(Math.cos(i / 4 * 6.28) * 0.8, 12 + i * 3, Math.sin(i / 4 * 6.28) * 0.8)
    mast.add(beacon)
  }
  mast.position.set(30, 0, -32)
  add(mast, { collide: true })
  // guy wires
  const wireGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(30, 22, -32), new THREE.Vector3(21, 0, -24),
    new THREE.Vector3(30, 18, -32), new THREE.Vector3(38, 0, -24),
    new THREE.Vector3(30, 14, -32), new THREE.Vector3(22, 0, -40),
  ])
  scene.add(new THREE.LineSegments(wireGeo, new THREE.LineBasicMaterial({ color: 0x556468, transparent: true, opacity: 0.4 })))

  // ---------- outer world silhouette ----------
  const cityMat = new THREE.MeshStandardMaterial({ color: 0x0b1117, roughness: 0.95, metalness: 0.05 })
  const winMat = new THREE.MeshBasicMaterial({ map: tex.windows, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false })
  const citySpots = [
    [-52, -55, 14, 24, 12], [-20, -62, 22, 16, 16], [22, -58, 18, 30, 14],
    [58, -40, 16, 20, 18], [62, 18, 22, 18, 14], [46, 58, 18, 26, 16],
    [8, 62, 26, 20, 12], [-36, 60, 18, 30, 14], [-62, 28, 20, 22, 18], [-58, -22, 14, 18, 10],
  ]
  for (const [x, z, w, h, d] of citySpots) {
    const b = box(w, h, d, cityMat, x, h / 2, z)
    scene.add(b)
    const win = new THREE.Mesh(new THREE.PlaneGeometry(w * 0.85, h * 0.7), winMat)
    win.position.set(x, h / 2, z + (z > 0 ? -d / 2 - 0.05 : d / 2 + 0.05))
    if (z > 0) win.rotation.y = Math.PI
    scene.add(win)
  }
  // distant smoke stacks
  for (const [x, z] of [[-55, -35], [48, 42]]) {
    const stack = cyl(1.4, 2.1, 34, MAT.concreteDark, x, 17, z, 12)
    scene.add(stack)
  }

  // smoke plumes
  const smokeTex = spriteTexture('smoke')
  const smokeSprites = []
  for (const [sx, sz, n] of [[-55, -35, 12], [48, 42, 10]]) {
    for (let i = 0; i < n; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: smokeTex, color: 0x2c3238, transparent: true, opacity: 0.05, depthWrite: false }))
      s.position.set(sx + rand(-2, 2), 33 + i * 2.4, sz + rand(-2, 2))
      s.scale.setScalar(5 + i * 1.1)
      scene.add(s)
      smokeSprites.push({ sprite: s, baseX: s.position.x, baseZ: s.position.z, phase: rand(0, 6), speed: rand(0.06, 0.14) })
    }
  }

  // ground fog banks
  const fogSprites = []
  for (let i = 0; i < 15; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: smokeTex, color: 0x263543, transparent: true, opacity: 0.035, depthWrite: false }))
    s.position.set(rand(-34, 34), rand(0.4, 1.8), rand(-34, 34))
    s.scale.set(rand(9, 16), rand(4, 7), 1)
    scene.add(s)
    fogSprites.push({ sprite: s, phase: rand(0, 6), speed: rand(0.03, 0.09) })
  }

  // hanging cable silhouettes between poles
  const cableMat = new THREE.LineBasicMaterial({ color: 0x121a1e, transparent: true, opacity: 0.8 })
  for (const [x1, z1, x2, z2, y] of [[-34, -8, -34, 22, 9], [34, -20, 34, 14, 8], [-20, 34.5, 18, 34.5, 7.5]]) {
    const pts = []
    for (let i = 0; i <= 24; i++) {
      const t = i / 24
      const sag = Math.sin(t * Math.PI) * 1.8
      pts.push(new THREE.Vector3(x1 + (x2 - x1) * t, y - sag, z1 + (z2 - z1) * t))
    }
    scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), cableMat))
  }

  // ---------- rain ----------
  const rainCount = 2600
  const rainGeo = new THREE.BufferGeometry()
  const rainPos = new Float32Array(rainCount * 2 * 3)
  const rainSeed = new Float32Array(rainCount * 2)
  const rainEnd = new Float32Array(rainCount * 2)
  for (let i = 0; i < rainCount; i++) {
    const x = rand(-22, 22), y = rand(0, 22), z = rand(-22, 22), seed = Math.random()
    for (let j = 0; j < 2; j++) {
      const idx = (i * 2 + j) * 3
      rainPos[idx] = x; rainPos[idx + 1] = y; rainPos[idx + 2] = z
      rainSeed[i * 2 + j] = seed
      rainEnd[i * 2 + j] = j
    }
  }
  rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3))
  rainGeo.setAttribute('seed', new THREE.BufferAttribute(rainSeed, 1))
  rainGeo.setAttribute('end', new THREE.BufferAttribute(rainEnd, 1))
  const rainMat = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    uniforms: { time: { value: 0 }, playerPos: { value: new THREE.Vector3() }, opacity: { value: 0.34 } },
    vertexShader: `
      attribute float seed; attribute float end; uniform float time; uniform vec3 playerPos; varying float vA;
      void main(){
        vec3 p = position;
        vec2 rel = mod(p.xz - playerPos.xz + 22.0, 44.0) - 22.0;
        float speed = 14.0 + seed * 9.0;
        float y = mod(p.y - time * speed, 22.0);
        p.x = playerPos.x + rel.x + time * 0.8;
        p.z = playerPos.z + rel.y + time * 1.6;
        p.y = y;
        if (end > 0.5) { p.y -= 0.55; p.x -= 0.03; p.z -= 0.06; }
        vA = 0.15 + seed * 0.35;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }
    `,
    fragmentShader: `varying float vA; uniform float opacity; void main(){ gl_FragColor = vec4(0.55,0.68,0.8, vA * opacity); }`,
  })
  const rain = new THREE.LineSegments(rainGeo, rainMat)
  rain.frustumCulled = false
  scene.add(rain)

  // floating embers / dust
  const dustCount = 230
  const dustGeo = new THREE.BufferGeometry()
  const dustPos = new Float32Array(dustCount * 3)
  const dustSeed = new Float32Array(dustCount)
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = rand(-34, 34); dustPos[i * 3 + 1] = rand(0.2, 12); dustPos[i * 3 + 2] = rand(-34, 34)
    dustSeed[i] = Math.random()
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
  dustGeo.setAttribute('seed', new THREE.BufferAttribute(dustSeed, 1))
  const dustMat = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    uniforms: { time: { value: 0 }, map: { value: spriteTexture('glow') }, opacity: { value: 0.35 } },
    vertexShader: `attribute float seed; uniform float time; varying float vA; void main(){ vec3 p=position; p.y += sin(time*0.3+seed*20.0)*0.5; p.x += sin(time*0.11+seed*30.0)*0.7; p.z += cos(time*0.09+seed*20.0)*0.7; vec4 mv=modelViewMatrix*vec4(p,1.0); gl_PointSize=(2.0+seed*4.0)*(90.0/-mv.z); gl_Position=projectionMatrix*mv; vA=0.2+seed*0.6; }`,
    fragmentShader: `uniform sampler2D map; varying float vA; uniform float opacity; void main(){ vec4 t=texture2D(map,gl_PointCoord); gl_FragColor=vec4(0.65,0.73,0.8,t.a*vA*opacity); }`,
  })
  const dust = new THREE.Points(dustGeo, dustMat)
  dust.frustumCulled = false
  scene.add(dust)

  // ---------- spawn / cover / player ----------
  const playerSpawn = new THREE.Vector3(0, 0, 20)
  enemySpawnPoints.push(
    new THREE.Vector3(0, 0, -31), new THREE.Vector3(0, 0, 31), new THREE.Vector3(-31, 0, 0), new THREE.Vector3(31, 0, 0),
    new THREE.Vector3(-27, 0, -27), new THREE.Vector3(27, 0, 27), new THREE.Vector3(-27, 0, 27), new THREE.Vector3(27, 0, -27),
    new THREE.Vector3(-12, 0, -30), new THREE.Vector3(14, 0, 30)
  )
  // spawn flare markers (subtle red ground glow)
  for (const sp of enemySpawnPoints) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 1.4, 24), new THREE.MeshBasicMaterial({ color: 0xff2a18, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }))
    ring.rotation.x = -Math.PI / 2
    ring.position.set(sp.x, 0.02, sp.z)
    scene.add(ring)
  }

  // ---------- static minimap ----------
  const mapCanvas = document.createElement('canvas')
  mapCanvas.width = mapCanvas.height = 400
  const mctx = mapCanvas.getContext('2d')
  const mapScale = 400 / 80
  const toMap = (v) => (v + 40) * mapScale
  mctx.fillStyle = '#071015'; mctx.fillRect(0, 0, 400, 400)
  mctx.strokeStyle = 'rgba(120,190,210,.08)'; mctx.lineWidth = 1
  for (let i = 0; i <= 400; i += 20) { mctx.beginPath(); mctx.moveTo(i, 0); mctx.lineTo(i, 400); mctx.stroke(); mctx.beginPath(); mctx.moveTo(0, i); mctx.lineTo(400, i); mctx.stroke() }
  // colliders as blocks
  for (const c of colliders) {
    mctx.fillStyle = 'rgba(130,160,170,.24)'
    mctx.strokeStyle = 'rgba(160,200,215,.28)'
    mctx.fillRect(toMap(c.minX), toMap(c.minZ), (c.maxX - c.minX) * mapScale, (c.maxZ - c.minZ) * mapScale)
    mctx.strokeRect(toMap(c.minX), toMap(c.minZ), (c.maxX - c.minX) * mapScale, (c.maxZ - c.minZ) * mapScale)
  }
  mctx.fillStyle = 'rgba(255,180,87,.35)'; mctx.strokeStyle = 'rgba(255,190,100,.7)'
  mctx.fillRect(toMap(platform.minX), toMap(platform.minZ), (platform.maxX - platform.minX) * mapScale, (platform.maxZ - platform.minZ) * mapScale)
  mctx.strokeRect(toMap(platform.minX), toMap(platform.minZ), (platform.maxX - platform.minX) * mapScale, (platform.maxZ - platform.minZ) * mapScale)
  mctx.strokeStyle = 'rgba(130,230,255,.25)'; mctx.lineWidth = 2; mctx.strokeRect(6, 6, 388, 388)

  // ---------- update ----------
  const tmpV = new THREE.Vector3(), tmpQ = new THREE.Quaternion(), up = new THREE.Vector3(0, -1, 0)
  function update(dt, time, playerPos) {
    skyMat.uniforms.time.value = time
    rainMat.uniforms.time.value = time
    rainMat.uniforms.playerPos.value.copy(playerPos)
    dustMat.uniforms.time.value = time

    if (playerPos) {
      // searchlight sweeps
      const a = time * 0.17
      searchTarget.position.set(Math.cos(a) * 16, 0, Math.sin(a * 0.8 + 1) * 15)
      const dir = tmpV.copy(searchTarget.position).sub(searchSpot.position)
      const len = dir.length()
      dir.normalize()
      searchCone.position.copy(searchSpot.position).addScaledVector(dir, len / 2)
      tmpQ.setFromUnitVectors(up, dir)
      searchCone.quaternion.copy(tmpQ)
      searchCone.scale.set(1, len / 48, 1)
    }

    for (const b of beacons) {
      const pulse = 0.5 + 0.5 * Math.sin(time * 3.2 + b.phase)
      if (b.lamp?.material) b.lamp.material.color.setRGB(1, 0.1 + pulse * 0.25, 0.06)
      if (b.lamp2?.material) b.lamp2.material.color.setRGB(1, 0.1 + pulse * 0.25, 0.06)
      if (b.glow) b.glow.material.opacity = 0.2 + pulse * 0.45
    }
    for (const f of flickerLights) {
      const flick = 0.88 + 0.12 * Math.sin(time * 17 * f.rate + f.phase) * Math.sin(time * 5.3 + f.phase * 2)
      f.spot.intensity = f.base * flick
      f.cone.material.opacity = 0.026 * flick
    }
    for (const s of smokeSprites) {
      s.sprite.position.y += dt * s.speed
      s.sprite.position.x = s.baseX + Math.sin(time * 0.12 + s.phase) * 3
      s.sprite.position.z = s.baseZ + Math.cos(time * 0.1 + s.phase) * 3
      if (s.sprite.position.y > 60) s.sprite.position.y = 32
    }
    for (const f of fogSprites) {
      f.sprite.position.x += Math.sin(time * 0.04 + f.phase) * dt * f.speed
      f.sprite.position.z += Math.cos(time * 0.03 + f.phase) * dt * f.speed
    }
  }

  function groundHeightAt(x, z) {
    if (x > platform.minX && x < platform.maxX && z > platform.minZ && z < platform.maxZ) return platform.height
    for (const r of platform.ramps) {
      if (Math.abs(x - r.x) < r.w / 2 && z >= Math.min(r.z0, r.z1) && z <= Math.max(r.z0, r.z1)) {
        const t = (z - r.z0) / (r.z1 - r.z0)
        return platform.height * (1 - t)
      }
    }
    return 0
  }

  function colliderAt(x, z, radius, feetY, height) {
    for (const c of colliders) {
      if (feetY + height <= c.minY + 0.05 || feetY >= c.maxY - 0.02) continue
      const cx = Math.max(c.minX, Math.min(x, c.maxX))
      const cz = Math.max(c.minZ, Math.min(z, c.maxZ))
      const dx = x - cx, dz = z - cz
      if (dx * dx + dz * dz < radius * radius) return c
    }
    return null
  }

  function boundsClamp(pos, radius) {
    pos.x = Math.max(ARENA.minX + radius, Math.min(ARENA.maxX - radius, pos.x))
    pos.z = Math.max(ARENA.minZ + radius, Math.min(ARENA.maxZ - radius, pos.z))
  }

  return {
    scene, sky, environment, moonLight, hemi, MAT, tex, colliders, raycastTargets, coverPoints,
    enemySpawnPoints, playerSpawn, platform, groundHeightAt, colliderAt, boundsClamp, update,
    staticMap: mapCanvas, mapScale, toMap,
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.dry = null
    this.wet = null
    this.convolver = null
    this.noise = null
    this.volume = 0.6
    this.muted = false
    this.ready = false
    this.intensity = 0
    this.ambient = null
    this.lastFoot = 0
    this.thunderTimer = 8 + Math.random() * 14
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    const ctx = this.ctx = new AC()
    const master = this.master = ctx.createGain()
    master.gain.value = this.muted ? 0 : this.volume
    const comp = ctx.createDynamicsCompressor()
    comp.threshold.value = -14
    comp.knee.value = 18
    comp.ratio.value = 4
    comp.attack.value = 0.004
    comp.release.value = 0.2
    master.connect(comp)
    comp.connect(ctx.destination)

    this.dry = ctx.createGain()
    this.dry.gain.value = 0.92
    this.dry.connect(master)
    this.convolver = ctx.createConvolver()
    this.convolver.buffer = this.makeImpulse(2.4, 3.2)
    this.wet = ctx.createGain()
    this.wet.gain.value = 0.16
    this.convolver.connect(this.wet)
    this.wet.connect(master)

    const len = ctx.sampleRate * 2
    const buf = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    this.noise = buf

    this.startAmbient()
    this.ready = true
  }

  makeImpulse(duration, decay) {
    const ctx = this.ctx
    const rate = ctx.sampleRate
    const len = Math.floor(rate * duration)
    const buf = ctx.createBuffer(2, len, rate)
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch)
      for (let i = 0; i < len; i++) {
        const t = i / len
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay) * (i < 200 ? i / 200 : 1)
      }
    }
    return buf
  }

  startAmbient() {
    const ctx = this.ctx
    const amb = ctx.createGain()
    amb.gain.value = 0.22
    amb.connect(this.dry)
    this.ambient = amb

    const wind = ctx.createBufferSource()
    wind.buffer = this.noise
    wind.loop = true
    const wf = ctx.createBiquadFilter()
    wf.type = 'lowpass'; wf.frequency.value = 520; wf.Q.value = 0.6
    const wg = ctx.createGain(); wg.gain.value = 0.055
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.07
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 0.028
    lfo.connect(lfoGain); lfoGain.connect(wg.gain)
    wind.connect(wf); wf.connect(wg); wg.connect(amb)
    wind.start(); lfo.start()

    const rain = ctx.createBufferSource()
    rain.buffer = this.noise
    rain.loop = true
    const rf = ctx.createBiquadFilter()
    rf.type = 'highpass'; rf.frequency.value = 1400; rf.Q.value = 0.4
    const rg = ctx.createGain(); rg.gain.value = 0.018
    rain.connect(rf); rf.connect(rg); rg.connect(amb)
    rain.start()

    const droneGain = ctx.createGain(); droneGain.gain.value = 0.042
    const droneFilter = ctx.createBiquadFilter(); droneFilter.type = 'lowpass'; droneFilter.frequency.value = 190
    droneGain.connect(droneFilter); droneFilter.connect(amb)
    for (const [f, det, g] of [[41.2, 0, 1], [55, 0.4, 0.7], [82.4, -0.3, 0.35]]) {
      const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f; o.detune.value = det * 100
      const og = ctx.createGain(); og.gain.value = g
      o.connect(og); og.connect(droneGain); o.start()
    }
    const pulse = ctx.createOscillator(); pulse.frequency.value = 0.11
    const pulseGain = ctx.createGain(); pulseGain.gain.value = 0.022
    pulse.connect(pulseGain); pulseGain.connect(droneGain.gain); pulse.start()
  }

  setVolume(v) {
    this.volume = Math.max(0, Math.min(1, v))
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, 0.05)
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : this.volume, this.ctx.currentTime, 0.03)
  }

  setIntensity(v) {
    this.intensity = v
    if (!this.ready) return
    const t = this.ctx.currentTime
    this.ambient?.gain.setTargetAtTime(0.2 + v * 0.1, t, 1.5)
  }

  now() { return this.ctx ? this.ctx.currentTime : 0 }

  route(node, pan = 0, wet = 0.2) {
    const ctx = this.ctx
    const p = ctx.createStereoPanner()
    p.pan.value = Math.max(-1, Math.min(1, pan))
    node.connect(p)
    p.connect(this.dry)
    if (wet > 0) {
      const s = ctx.createGain(); s.gain.value = wet
      p.connect(s); s.connect(this.convolver)
    }
  }

  noiseSource(duration, { rate = 1, type = 'lowpass', freq = 1200, q = 0.7, gain = 0.2, attack = 0.003, pan = 0, wet = 0.2 } = {}) {
    if (!this.ready || this.muted) return
    const ctx = this.ctx, t = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    src.playbackRate.value = rate
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(f); f.connect(g); this.route(g, pan, wet)
    src.start(t, Math.random() * 1.2, duration + 0.05)
  }

  tone(freq, duration, { type = 'sine', gain = 0.1, endFreq = null, attack = 0.004, pan = 0, wet = 0.1, delay = 0 } = {}) {
    if (!this.ready || this.muted) return
    const ctx = this.ctx
    const t = ctx.currentTime + delay
    const o = ctx.createOscillator(); o.type = type; o.frequency.setValueAtTime(freq, t)
    if (endFreq) o.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    o.connect(g); this.route(g, pan, wet)
    o.start(t); o.stop(t + duration + 0.02)
  }

  shot(kind = 'rifle') {
    if (!this.ready) return
    const rifle = kind !== 'pistol'
    this.noiseSource(rifle ? 0.22 : 0.16, { freq: rifle ? 3800 : 3000, q: 0.9, gain: 0.28, wet: 0.3, pan: (Math.random() - 0.5) * 0.1 })
    this.noiseSource(0.06, { type: 'highpass', freq: 2200, gain: 0.16, wet: 0.12 })
    this.tone(rifle ? 118 : 150, 0.13, { endFreq: 48, gain: 0.34, wet: 0.2, type: 'sine' })
    this.tone(rifle ? 280 : 340, 0.045, { endFreq: 90, gain: 0.08, type: 'triangle', wet: 0.1 })
  }

  enemyShot(distance = 10, pan = 0, heavy = false) {
    if (!this.ready) return
    const att = 1 / (1 + distance * 0.055)
    this.noiseSource(heavy ? 0.24 : 0.18, { freq: 2600, gain: 0.24 * att, pan, wet: 0.35 })
    this.tone(heavy ? 80 : 105, 0.16, { endFreq: 42, gain: 0.28 * att, pan, wet: 0.2 })
  }

  dryFire() { this.tone(1300, 0.03, { type: 'square', gain: 0.05, wet: 0.05 }) }

  reloadStep(stage = 0) {
    if (!this.ready) return
    const t = this.now()
    if (stage === 0) { this.tone(760, 0.05, { type: 'square', gain: 0.045, wet: 0.04 }); this.noiseSource(0.08, { type: 'bandpass', freq: 1200, gain: 0.05, wet: 0.05 }) }
    else if (stage === 1) { this.noiseSource(0.13, { type: 'bandpass', freq: 700, gain: 0.06, wet: 0.08 }) }
    else if (stage === 2) { this.tone(420, 0.05, { type: 'square', gain: 0.06, wet: 0.04 }); this.noiseSource(0.06, { type: 'highpass', freq: 1800, gain: 0.06, wet: 0.04 }) }
    else { this.tone(980, 0.04, { type: 'square', gain: 0.04, wet: 0.03 }) }
  }

  footstep(run = false) {
    if (!this.ready || this.muted) return
    const now = this.now()
    if (now - this.lastFoot < 0.16) return
    this.lastFoot = now
    this.noiseSource(0.11, { type: 'bandpass', freq: run ? 380 : 300, q: 1.2, gain: run ? 0.055 : 0.035, wet: 0.12, pan: Math.random() * 0.1 })
    if (Math.random() > 0.6) this.noiseSource(0.05, { type: 'highpass', freq: 2600, gain: 0.012, wet: 0.06 })
  }

  hit(head = false, kill = false) {
    if (!this.ready) return
    this.tone(head ? 2100 : 1500, 0.05, { type: 'triangle', gain: head ? 0.09 : 0.055, endFreq: head ? 1500 : 1200, wet: 0.08 })
    if (kill) this.tone(660, 0.18, { type: 'triangle', gain: 0.08, endFreq: 990, delay: 0.03, wet: 0.12 })
  }

  explosion(distance = 0, pan = 0) {
    if (!this.ready) return
    const att = 1 / (1 + distance * 0.03)
    this.noiseSource(1.1, { freq: 330, q: 0.5, gain: 0.42 * att, pan, wet: 0.6 })
    this.noiseSource(0.25, { type: 'highpass', freq: 900, gain: 0.2 * att, pan, wet: 0.35 })
    this.tone(58, 0.9, { endFreq: 26, gain: 0.5 * att, pan, wet: 0.4 })
  }

  grenadeThrow() {
    this.noiseSource(0.18, { type: 'bandpass', freq: 900, q: 0.8, gain: 0.05, wet: 0.08 })
  }

  melee() {
    this.noiseSource(0.2, { type: 'bandpass', freq: 600, q: 1.6, gain: 0.1, wet: 0.1 })
    this.tone(180, 0.12, { endFreq: 80, gain: 0.06, wet: 0.1 })
  }

  pickup() {
    this.tone(880, 0.12, { type: 'triangle', gain: 0.08, wet: 0.12 })
    this.tone(1320, 0.16, { type: 'triangle', gain: 0.06, delay: 0.08, wet: 0.12 })
  }

  waveStart(wave = 1) {
    if (!this.ready) return
    this.tone(55, 1.2, { type: 'sawtooth', gain: 0.08, endFreq: 82, wet: 0.3 })
    this.tone(110, 1.0, { type: 'triangle', gain: 0.06, endFreq: 110, delay: 0.1, wet: 0.3 })
    for (let i = 0; i < 3; i++) this.tone(440 + i * 110, 0.09, { type: 'square', gain: 0.03, delay: 0.18 * i, wet: 0.2 })
  }

  waveClear() {
    this.tone(392, 0.18, { type: 'triangle', gain: 0.07, wet: 0.2 })
    this.tone(523, 0.22, { type: 'triangle', gain: 0.07, delay: 0.14, wet: 0.2 })
    this.tone(659, 0.3, { type: 'triangle', gain: 0.06, delay: 0.28, wet: 0.2 })
  }

  victory() {
    const notes = [392, 523, 659, 784, 1046]
    notes.forEach((n, i) => this.tone(n, 0.5, { type: 'triangle', gain: 0.07, delay: i * 0.18, wet: 0.4 }))
    this.tone(98, 2.2, { type: 'sawtooth', gain: 0.05, endFreq: 130, wet: 0.3 })
  }

  defeat() {
    this.tone(196, 1.6, { type: 'sawtooth', gain: 0.07, endFreq: 55, wet: 0.4 })
    this.tone(147, 2.2, { type: 'triangle', gain: 0.05, endFreq: 42, wet: 0.4 })
  }

  damage() {
    this.noiseSource(0.18, { type: 'lowpass', freq: 420, gain: 0.15, wet: 0.2 })
    this.tone(70, 0.25, { endFreq: 40, gain: 0.1, wet: 0.1 })
  }

  heartbeat() {
    this.tone(58, 0.14, { endFreq: 38, gain: 0.12, wet: 0.05 })
    this.tone(52, 0.12, { endFreq: 36, gain: 0.08, delay: 0.18, wet: 0.05 })
  }

  thunder() {
    if (!this.ready) return
    this.noiseSource(2.6, { freq: 180, q: 0.4, gain: 0.12, attack: 0.08, wet: 0.7 })
    this.tone(38, 2.2, { endFreq: 20, gain: 0.12, wet: 0.5 })
  }

  ui() { this.tone(620, 0.04, { type: 'square', gain: 0.03, wet: 0.03 }) }
}

import * as THREE from 'three'
import { decalTexture, spriteTexture } from './textures.js'

function rand(a = 0, b = 1) { return a + Math.random() * (b - a) }

class ParticleSystem {
  constructor(scene, max, { additive = false, map = 'glow', gravity = 9.8 } = {}) {
    this.max = max
    this.gravity = gravity
    this.particles = []
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3))
    geo.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1))
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alphas, 1))
    geo.setDrawRange(0, 0)
    const mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      uniforms: { map: { value: spriteTexture(map) }, opacity: { value: 1 } },
      vertexShader: `
        attribute float size; attribute float alpha; attribute vec3 color;
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vColor = color; vAlpha = alpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (420.0 / max(0.4, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D map; uniform float opacity; varying vec3 vColor; varying float vAlpha;
        void main(){
          vec4 t = texture2D(map, gl_PointCoord);
          if (t.a < 0.01) discard;
          gl_FragColor = vec4(vColor, t.a * vAlpha * opacity);
        }
      `,
    })
    this.mesh = new THREE.Points(geo, mat)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 3
    scene.add(this.mesh)
    this.geo = geo
  }

  spawn({ pos, vel, color = [1, 1, 1], size = 0.15, life = 0.6, gravity = this.gravity, drag = 0.9, grow = 0, alpha = 1 }) {
    if (this.particles.length >= this.max) this.particles.shift()
    this.particles.push({
      pos: pos.clone(), vel: vel.clone(), color, size, life, maxLife: life,
      gravity, drag, grow, alpha,
    })
  }

  update(dt) {
    const ps = this.particles
    let n = 0
    for (let i = ps.length - 1; i >= 0; i--) {
      const p = ps[i]
      p.life -= dt
      if (p.life <= 0) { ps.splice(i, 1); continue }
      p.vel.y -= p.gravity * dt
      const d = Math.pow(p.drag, dt * 60)
      p.vel.x *= d; p.vel.z *= d; p.vel.y *= d
      p.pos.addScaledVector(p.vel, dt)
      if (p.pos.y < 0.02 && p.gravity > 0) { p.pos.y = 0.02; p.vel.y *= -0.25; p.vel.x *= 0.55; p.vel.z *= 0.55 }
      p.size += p.grow * dt
    }
    for (let i = 0; i < ps.length && n < this.max; i++) {
      const p = ps[i]
      const t = p.life / p.maxLife
      this.positions[n * 3] = p.pos.x
      this.positions[n * 3 + 1] = p.pos.y
      this.positions[n * 3 + 2] = p.pos.z
      this.colors[n * 3] = p.color[0]
      this.colors[n * 3 + 1] = p.color[1]
      this.colors[n * 3 + 2] = p.color[2]
      this.sizes[n] = p.size
      this.alphas[n] = p.alpha * Math.min(1, t * 2.2) * Math.min(1, p.life * 8)
      n++
    }
    this.geo.setDrawRange(0, n)
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.color.needsUpdate = true
    this.geo.attributes.size.needsUpdate = true
    this.geo.attributes.alpha.needsUpdate = true
  }
}

export class Effects {
  constructor(scene, world, camera) {
    this.scene = scene
    this.world = world
    this.camera = camera
    this.time = 0
    this.sparks = new ParticleSystem(scene, 700, { additive: true, map: 'spark', gravity: 9.8 })
    this.smoke = new ParticleSystem(scene, 500, { additive: false, map: 'smoke', gravity: -0.35 })
    this.fire = new ParticleSystem(scene, 260, { additive: true, map: 'flash', gravity: -1.5 })
    this.tracers = []
    for (let i = 0; i < 38; i++) {
      const m = new THREE.Mesh(
        new THREE.CylinderGeometry(0.014, 0.014, 1, 5, 1, true),
        new THREE.MeshBasicMaterial({ color: 0xffd9a0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
      )
      m.visible = false
      m.frustumCulled = false
      scene.add(m)
      this.tracers.push({ mesh: m, life: 0, maxLife: 0.07 })
    }
    this.tracerIndex = 0
    this.flashLight = new THREE.PointLight(0xffb060, 0, 22, 2)
    this.flashLight.position.set(0, 2, 0)
    scene.add(this.flashLight)
    this.flashIntensity = 0
    this.flashPos = new THREE.Vector3()

    this.muzzle = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('flash'), color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }))
    this.muzzle.scale.set(1, 1, 1)
    scene.add(this.muzzle)
    this.muzzleLife = 0

    this.decals = []
    this.decalGeo = new THREE.PlaneGeometry(0.25, 0.25)
    for (let i = 0; i < 70; i++) {
      const m = new THREE.Mesh(this.decalGeo, new THREE.MeshBasicMaterial({ map: decalTexture('bullet'), transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 }))
      m.visible = false
      scene.add(m)
      this.decals.push({ mesh: m, life: 0 })
    }
    this.decalIndex = 0
    this.scorches = []
    for (let i = 0; i < 8; i++) {
      const m = new THREE.Mesh(new THREE.CircleGeometry(2.2, 24), new THREE.MeshBasicMaterial({ map: decalTexture('scorch'), transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 }))
      m.rotation.x = -Math.PI / 2
      m.visible = false
      scene.add(m)
      this.scorches.push({ mesh: m, life: 0 })
    }
    this.scorchIndex = 0

    this.rings = []
    for (let i = 0; i < 5; i++) {
      const m = new THREE.Mesh(new THREE.RingGeometry(0.9, 1.05, 32), new THREE.MeshBasicMaterial({ color: 0xffb060, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }))
      m.rotation.x = -Math.PI / 2
      m.visible = false
      scene.add(m)
      this.rings.push({ mesh: m, life: 0, max: 0, size: 1 })
    }
    this.ringIndex = 0

    this.casings = []
    const casingGeo = new THREE.CylinderGeometry(0.009, 0.009, 0.032, 5)
    const casingMat = new THREE.MeshStandardMaterial({ color: 0xb08b42, metalness: 0.9, roughness: 0.3, emissive: 0x1a1004 })
    for (let i = 0; i < 22; i++) {
      const m = new THREE.Mesh(casingGeo, casingMat)
      m.visible = false
      m.castShadow = false
      scene.add(m)
      this.casings.push({ mesh: m, vel: new THREE.Vector3(), spin: new THREE.Vector3(), life: 0 })
    }
    this.casingIndex = 0
    this.shake = 0
    this.onShake = null
  }

  tracer(from, to, color = 0xffd8a0, opacity = 0.85) {
    const t = this.tracers[this.tracerIndex++ % this.tracers.length]
    const dir = to.clone().sub(from)
    const len = dir.length()
    if (len < 0.1) return
    const m = t.mesh
    m.visible = true
    m.position.copy(from).addScaledVector(dir, 0.5)
    m.scale.set(1, len, 1)
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize())
    m.material.color.setHex(color)
    m.material.opacity = opacity
    t.life = t.maxLife
  }

  muzzleFlash(pos, dir, scale = 1) {
    this.muzzle.position.copy(pos)
    this.muzzle.scale.setScalar(rand(0.55, 0.9) * scale)
    this.muzzle.material.rotation = rand(0, 6.28)
    this.muzzle.material.opacity = 1
    this.muzzleLife = 0.06
    this.flashPos.copy(pos)
    this.flashLight.position.copy(pos)
    this.flashIntensity = 16 * scale
    for (let i = 0; i < 3; i++) {
      this.smoke.spawn({
        pos: pos.clone().addScaledVector(dir, rand(0.05, 0.25)),
        vel: dir.clone().multiplyScalar(rand(0.5, 1.6)).add(new THREE.Vector3(rand(-0.2, 0.2), rand(0, 0.3), rand(-0.2, 0.2))),
        color: [0.42, 0.42, 0.42], size: rand(0.2, 0.4), life: rand(0.5, 1.1), gravity: -0.2, drag: 0.94, grow: 0.6, alpha: 0.32,
      })
    }
    for (let i = 0; i < 2; i++) {
      this.sparks.spawn({
        pos: pos.clone(), vel: dir.clone().multiplyScalar(rand(2, 6)).add(new THREE.Vector3(rand(-0.8, 0.8), rand(-0.5, 0.5), rand(-0.8, 0.8))),
        color: [1, 0.7, 0.32], size: rand(0.04, 0.08), life: rand(0.08, 0.2), gravity: 4, drag: 0.9,
      })
    }
  }

  impact(point, normal, { metal = false, force = 1 } = {}) {
    const n = normal.clone().normalize()
    const count = Math.round(rand(5, 10) * force)
    for (let i = 0; i < count; i++) {
      const v = n.clone().multiplyScalar(rand(1.2, 4.5)).add(new THREE.Vector3(rand(-1.9, 1.9), rand(-0.8, 2.2), rand(-1.9, 1.9)))
      this.sparks.spawn({
        pos: point.clone().addScaledVector(n, 0.03), vel: v,
        color: metal ? [1, 0.8, 0.45] : [1, 0.62, 0.25], size: rand(0.025, 0.07), life: rand(0.12, 0.42), gravity: 8, drag: 0.9,
      })
    }
    for (let i = 0; i < 2; i++) {
      this.smoke.spawn({
        pos: point.clone().addScaledVector(n, 0.05),
        vel: n.clone().multiplyScalar(rand(0.15, 0.6)).add(new THREE.Vector3(rand(-0.2, 0.2), rand(0, 0.4), rand(-0.2, 0.2))),
        color: [0.32, 0.31, 0.29], size: rand(0.15, 0.32), life: rand(0.5, 1.2), gravity: -0.1, drag: 0.93, grow: 0.35, alpha: 0.35,
      })
    }
    this.addDecal(point, n, 0.22)
  }

  addDecal(point, normal, size = 0.22) {
    const d = this.decals[this.decalIndex++ % this.decals.length]
    const m = d.mesh
    m.visible = true
    m.position.copy(point).addScaledVector(normal, 0.012)
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal)
    m.rotateZ(rand(0, 6.28))
    m.scale.setScalar(size / 0.25 * rand(0.8, 1.25))
    m.material.opacity = 0.9
    d.life = 22
  }

  blood(point, dir, amount = 1) {
    const n = Math.round(rand(8, 14) * amount)
    for (let i = 0; i < n; i++) {
      this.sparks.spawn({
        pos: point.clone(), vel: dir.clone().multiplyScalar(rand(0.5, 2.2)).add(new THREE.Vector3(rand(-1.4, 1.4), rand(0, 2.4), rand(-1.4, 1.4))),
        color: [0.55, 0.04, 0.03], size: rand(0.03, 0.09), life: rand(0.2, 0.6), gravity: 7, drag: 0.9,
      })
    }
    for (let i = 0; i < 2; i++) {
      this.smoke.spawn({
        pos: point.clone(), vel: new THREE.Vector3(rand(-0.2, 0.2), rand(0, 0.4), rand(-0.2, 0.2)),
        color: [0.3, 0.03, 0.02], size: rand(0.2, 0.36), life: rand(0.5, 1), gravity: -0.1, drag: 0.92, grow: 0.5, alpha: 0.3,
      })
    }
  }

  explosion(pos, { radius = 4, color = 0xff8a3c } = {}) {
    for (let i = 0; i < 55; i++) {
      const dir = new THREE.Vector3(rand(-1, 1), rand(-0.2, 1), rand(-1, 1)).normalize()
      this.fire.spawn({
        pos: pos.clone().add(new THREE.Vector3(0, rand(0.1, 0.6), 0)),
        vel: dir.multiplyScalar(rand(2, 11)), color: [1, rand(0.35, 0.75), rand(0.1, 0.25)],
        size: rand(0.35, 0.9), life: rand(0.25, 0.8), gravity: -1.5, drag: 0.9, grow: 0.8, alpha: 0.9,
      })
    }
    for (let i = 0; i < 40; i++) {
      const dir = new THREE.Vector3(rand(-1, 1), rand(0, 1), rand(-1, 1)).normalize()
      this.sparks.spawn({
        pos: pos.clone(), vel: dir.multiplyScalar(rand(5, 18)), color: [1, rand(0.65, 0.9), 0.35],
        size: rand(0.03, 0.09), life: rand(0.4, 1.2), gravity: 11, drag: 0.92,
      })
    }
    for (let i = 0; i < 28; i++) {
      const dir = new THREE.Vector3(rand(-1, 1), rand(0.2, 1), rand(-1, 1)).normalize()
      this.smoke.spawn({
        pos: pos.clone().add(new THREE.Vector3(0, rand(0, 0.8), 0)), vel: dir.multiplyScalar(rand(0.8, 3.2)),
        color: [0.13, 0.12, 0.11], size: rand(0.8, 1.6), life: rand(1.4, 2.8), gravity: -0.5, drag: 0.93, grow: 1.2, alpha: 0.6,
      })
    }
    this.flashLight.position.copy(pos); this.flashLight.position.y += 1
    this.flashIntensity = 90
    const r = this.rings[this.ringIndex++ % this.rings.length]
    r.mesh.visible = true; r.mesh.position.set(pos.x, 0.06, pos.z); r.mesh.scale.setScalar(0.2)
    r.mesh.material.color.setHex(color); r.mesh.material.opacity = 0.75
    r.life = 0.5; r.max = 0.5; r.size = radius
    const sc = this.scorches[this.scorchIndex++ % this.scorches.length]
    sc.mesh.visible = true; sc.mesh.position.set(pos.x, 0.02, pos.z)
    sc.mesh.scale.setScalar(radius / 2.2 * rand(0.9, 1.2))
    sc.mesh.material.opacity = 0.85; sc.life = 30
    this.shake = Math.max(this.shake, 0.45)
    this.onShake?.(0.55, 0.5)
  }

  casing(pos, dir) {
    const c = this.casings[this.casingIndex++ % this.casings.length]
    c.mesh.visible = true
    c.mesh.position.copy(pos)
    c.vel.set(rand(0.6, 1.8), rand(0.8, 2), rand(-0.4, 0.4)).addScaledVector(dir, 0.4)
    c.spin.set(rand(-20, 20), rand(-20, 20), rand(-20, 20))
    c.life = 2.4
  }

  update(dt, time) {
    this.time = time
    this.sparks.update(dt)
    this.smoke.update(dt)
    this.fire.update(dt)
    for (const t of this.tracers) {
      if (t.life > 0) {
        t.life -= dt
        t.mesh.material.opacity = Math.max(0, t.life / t.maxLife) * 0.9
        if (t.life <= 0) t.mesh.visible = false
      }
    }
    for (const d of this.decals) {
      if (d.life > 0) {
        d.life -= dt
        d.mesh.material.opacity = Math.min(0.9, d.life / 2)
        if (d.life <= 0) d.mesh.visible = false
      }
    }
    for (const s of this.scorches) {
      if (s.life > 0) {
        s.life -= dt
        s.mesh.material.opacity = Math.min(0.85, s.life / 6)
        if (s.life <= 0) s.mesh.visible = false
      }
    }
    for (const r of this.rings) {
      if (r.life > 0) {
        r.life -= dt
        const t = 1 - r.life / r.max
        r.mesh.scale.setScalar(0.2 + t * r.size)
        r.mesh.material.opacity = (1 - t) * 0.7
        if (r.life <= 0) r.mesh.visible = false
      }
    }
    for (const c of this.casings) {
      if (c.life > 0) {
        c.life -= dt
        c.vel.y -= 9.8 * dt
        c.mesh.position.addScaledVector(c.vel, dt)
        c.mesh.rotation.x += c.spin.x * dt
        c.mesh.rotation.y += c.spin.y * dt
        c.mesh.rotation.z += c.spin.z * dt
        if (c.mesh.position.y < 0.02) { c.mesh.position.y = 0.02; c.vel.y *= -0.35; c.vel.x *= 0.6; c.vel.z *= 0.6 }
        if (c.life <= 0) c.mesh.visible = false
      }
    }
    if (this.muzzleLife > 0) {
      this.muzzleLife -= dt
      this.muzzle.material.opacity = Math.max(0, this.muzzleLife / 0.06)
    } else {
      this.muzzle.material.opacity = 0
    }
    if (this.flashIntensity > 0) {
      this.flashIntensity = Math.max(0, this.flashIntensity - dt * 260)
      this.flashLight.intensity = this.flashIntensity
    } else {
      this.flashLight.intensity = 0
    }
    this.shake = Math.max(0, this.shake - dt * 1.8)
  }
}

