import * as THREE from 'three'
import { spriteTexture } from './textures.js'

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const lerp = (a, b, t) => a + (b - a) * t
const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
const rand = (a, b) => a + Math.random() * (b - a)

export const WEAPONS = [
  {
    id: 'rifle', name: 'VK-7 CARBINE', short: 'VK-7', mode: 'AUTO', kind: 'rifle',
    magSize: 30, reserveMax: 240, damage: 31, headMul: 2.35, rpm: 720, auto: true,
    reloadTime: 2.05, spreadHip: 0.017, spreadAds: 0.0022, moveSpread: 0.022,
    recoil: 0.0085, recoilYaw: 0.0035, adsFov: 56, range: 130,
  },
  {
    id: 'pistol', name: 'M9 SIDEARM', short: 'M9', mode: 'SEMI', kind: 'pistol',
    magSize: 15, reserveMax: 120, damage: 44, headMul: 2.5, rpm: 430, auto: false,
    reloadTime: 1.55, spreadHip: 0.012, spreadAds: 0.0018, moveSpread: 0.016,
    recoil: 0.012, recoilYaw: 0.004, adsFov: 60, range: 100,
  },
]

function metal(color, roughness = 0.42, metalness = 0.86) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness })
}

function buildRifle() {
  const g = new THREE.Group()
  const dark = metal(0x22282a, 0.38, 0.9)
  const black = metal(0x111516, 0.5, 0.72)
  const tan = new THREE.MeshStandardMaterial({ color: 0x8b7454, roughness: 0.78, metalness: 0.08 })
  const tanDark = new THREE.MeshStandardMaterial({ color: 0x5b4c37, roughness: 0.72, metalness: 0.12 })
  const glove = new THREE.MeshStandardMaterial({ color: 0x111413, roughness: 0.85, metalness: 0.02 })
  const sleeve = new THREE.MeshStandardMaterial({ color: 0x2b3029, roughness: 0.92, metalness: 0.01 })
  const accent = new THREE.MeshStandardMaterial({ color: 0x0a0c0c, emissive: 0x44d9ff, emissiveIntensity: 1.3, roughness: 0.4 })

  function box(w, h, d, mat, x, y, z, rx = 0, ry = 0, rz = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
    m.position.set(x, y, z); m.rotation.set(rx, ry, rz)
    g.add(m); return m
  }
  function cyl(r, len, mat, x, y, z, axis = 'z', seg = 12) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, seg), mat)
    m.position.set(x, y, z)
    if (axis === 'z') m.rotation.x = Math.PI / 2
    if (axis === 'x') m.rotation.z = Math.PI / 2
    g.add(m); return m
  }

  // receiver
  box(0.072, 0.095, 0.32, dark, 0, 0, -0.06)
  box(0.078, 0.055, 0.2, black, 0, -0.055, -0.03)
  box(0.046, 0.012, 0.5, black, 0, 0.052, -0.2)
  // handguard with vents
  box(0.064, 0.068, 0.31, tanDark, 0, 0.005, -0.37)
  for (let i = 0; i < 5; i++) {
    box(0.07, 0.009, 0.02, black, 0, 0.005, -0.27 - i * 0.052)
  }
  // barrel + suppressor
  cyl(0.012, 0.26, black, 0, 0.008, -0.59, 'z', 10)
  cyl(0.029, 0.17, dark, 0, 0.008, -0.79, 'z', 14)
  cyl(0.032, 0.02, black, 0, 0.008, -0.7, 'z', 14)
  // stock
  box(0.05, 0.075, 0.22, tan, 0, -0.004, 0.2)
  box(0.055, 0.09, 0.035, black, 0, -0.004, 0.315)
  box(0.03, 0.025, 0.16, tan, 0, 0.04, 0.2)
  // grip + trigger guard
  box(0.045, 0.14, 0.06, tanDark, 0, -0.115, 0.07, -0.18)
  box(0.012, 0.02, 0.09, black, 0, -0.07, 0.035)
  box(0.012, 0.04, 0.012, black, 0, -0.09, -0.005)
  // magazine
  const mag = box(0.048, 0.16, 0.09, black, 0, -0.15, -0.08, 0.12)
  box(0.052, 0.02, 0.095, dark, 0, -0.235, -0.07, 0.12)
  // optic
  box(0.028, 0.026, 0.1, black, 0, 0.072, -0.03)
  cyl(0.029, 0.105, dark, 0, 0.098, -0.03, 'z', 16)
  const lens1 = new THREE.Mesh(new THREE.CircleGeometry(0.026, 16), new THREE.MeshBasicMaterial({ color: 0x2d4a55, transparent: true, opacity: 0.45 }))
  lens1.position.set(0, 0.098, 0.024); g.add(lens1)
  const lens2 = lens1.clone(); lens2.position.z = -0.084; lens2.rotation.y = Math.PI; g.add(lens2)
  const dot = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('glow'), color: 0xff2a1a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }))
  dot.scale.set(0.012, 0.012, 1)
  dot.position.set(0, 0.098, -0.085)
  g.add(dot)
  // iron sights
  box(0.01, 0.026, 0.01, black, 0, 0.072, -0.52)
  box(0.034, 0.012, 0.012, black, 0, 0.064, -0.52)
  // charging handle / bolt
  box(0.028, 0.018, 0.06, black, 0.04, 0.03, 0.02)
  // small side display
  box(0.004, 0.025, 0.06, accent, -0.039, 0.03, -0.02)
  // rails
  for (let i = 0; i < 5; i++) box(0.012, 0.008, 0.028, black, -0.038, 0.058, -0.1 - i * 0.045)

  // hands and arms
  const rightHand = new THREE.Group()
  rightHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.075, 0.11), glove))
  rightHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.06, 0.04), glove))
  rightHand.children[1].position.set(-0.03, 0.01, -0.03)
  rightHand.position.set(0.012, -0.16, 0.06)
  g.add(rightHand)
  const rightSleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.038, 0.052, 0.26, 10), sleeve)
  rightSleeve.position.set(0.06, -0.3, 0.18)
  rightSleeve.rotation.set(0.45, 0, -0.35)
  g.add(rightSleeve)

  const leftHand = new THREE.Group()
  leftHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.065, 0.06, 0.12), glove))
  leftHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.035, 0.05), glove))
  leftHand.children[1].position.set(0.02, 0.03, 0.04)
  leftHand.position.set(-0.015, -0.09, -0.38)
  g.add(leftHand)
  const leftSleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.038, 0.055, 0.32, 10), sleeve)
  leftSleeve.position.set(-0.13, -0.24, -0.3)
  leftSleeve.rotation.set(0.7, 0, 0.55)
  g.add(leftSleeve)

  const muzzle = new THREE.Object3D()
  muzzle.position.set(0, 0.008, -0.89)
  g.add(muzzle)
  const flash = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('flash'), color: 0xffbb70, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }))
  flash.scale.setScalar(0.34)
  flash.position.copy(muzzle.position)
  g.add(flash)
  const flashLight = new THREE.PointLight(0xffa050, 0, 2.2, 2)
  flashLight.position.copy(muzzle.position)
  g.add(flashLight)

  g.userData = { mag, rightHand, leftHand, flash, flashLight, muzzle, dot, magBaseY: mag.position.y, dotBaseScale: 0.012 }
  return g
}

function buildPistol() {
  const g = new THREE.Group()
  const dark = metal(0x252b2d, 0.35, 0.92)
  const black = metal(0x101415, 0.55, 0.7)
  const tan = new THREE.MeshStandardMaterial({ color: 0x7c6248, roughness: 0.8, metalness: 0.06 })
  const glove = new THREE.MeshStandardMaterial({ color: 0x121514, roughness: 0.86 })
  const sleeve = new THREE.MeshStandardMaterial({ color: 0x2b3029, roughness: 0.92 })
  function box(w, h, d, mat, x, y, z, rx = 0, ry = 0, rz = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
    m.position.set(x, y, z); m.rotation.set(rx, ry, rz); g.add(m); return m
  }
  // slide/frame
  box(0.048, 0.058, 0.23, dark, 0, 0.025, -0.01)
  box(0.042, 0.032, 0.2, black, 0, -0.012, -0.005)
  box(0.02, 0.014, 0.06, black, 0, 0.058, -0.08)
  box(0.014, 0.012, 0.012, black, 0, 0.065, -0.005)
  box(0.012, 0.012, 0.012, black, 0, 0.062, 0.085)
  // barrel
  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.04, 10), black)
  barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.025, -0.13); g.add(barrel)
  // grip
  box(0.05, 0.16, 0.07, tan, 0, -0.085, 0.09, -0.18)
  box(0.054, 0.02, 0.074, black, 0, -0.168, 0.105, -0.18)
  // magazine base
  box(0.04, 0.012, 0.058, black, 0, -0.177, 0.105, -0.18)
  // trigger guard
  box(0.01, 0.02, 0.07, black, 0, -0.04, 0.02)
  box(0.01, 0.04, 0.01, black, 0, -0.055, -0.015)
  // suppressor-like muzzle
  const can = new THREE.Mesh(new THREE.CylinderGeometry(0.021, 0.021, 0.11, 12), dark)
  can.rotation.x = Math.PI / 2; can.position.set(0, 0.025, -0.2); g.add(can)
  const tip = new THREE.Mesh(new THREE.CircleGeometry(0.021, 12), black)
  tip.position.set(0, 0.025, -0.255); g.add(tip)
  // sights
  box(0.008, 0.016, 0.01, black, 0, 0.071, -0.08)
  box(0.008, 0.016, 0.01, black, 0, 0.071, 0.085)
  // hands
  const rightHand = new THREE.Group()
  rightHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.085, 0.11), glove))
  rightHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.06, 0.04), glove))
  rightHand.position.set(0.015, -0.1, 0.1)
  g.add(rightHand)
  const rightSleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.055, 0.26, 10), sleeve)
  rightSleeve.position.set(0.07, -0.25, 0.2); rightSleeve.rotation.set(0.5, 0, -0.3); g.add(rightSleeve)
  const leftHand = new THREE.Group()
  leftHand.add(new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.07, 0.1), glove))
  leftHand.position.set(-0.038, -0.075, 0.06); leftHand.rotation.z = -0.25
  g.add(leftHand)
  const leftSleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.038, 0.05, 0.28, 10), sleeve)
  leftSleeve.position.set(-0.08, -0.2, 0.18); leftSleeve.rotation.set(0.55, 0, 0.4); g.add(leftSleeve)

  const muzzle = new THREE.Object3D(); muzzle.position.set(0, 0.025, -0.27); g.add(muzzle)
  const flash = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('flash'), color: 0xffbe78, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }))
  flash.scale.setScalar(0.24); flash.position.copy(muzzle.position); g.add(flash)
  const flashLight = new THREE.PointLight(0xffa050, 0, 2, 2)
  flashLight.position.copy(muzzle.position); g.add(flashLight)

  g.userData = { mag: null, rightHand, leftHand, flash, flashLight, muzzle, dot: null, magBaseY: 0, dotBaseScale: 0.01 }
  return g
}

function buildKnife() {
  const g = new THREE.Group()
  const steel = new THREE.MeshStandardMaterial({ color: 0x9baab0, roughness: 0.25, metalness: 0.95 })
  const edge = new THREE.MeshStandardMaterial({ color: 0xdfe9ec, roughness: 0.15, metalness: 1 })
  const handle = new THREE.MeshStandardMaterial({ color: 0x181b19, roughness: 0.9 })
  const bladeShape = new THREE.Shape()
  bladeShape.moveTo(0, 0); bladeShape.lineTo(0.028, 0.04); bladeShape.lineTo(0.016, 0.28)
  bladeShape.lineTo(0, 0.34); bladeShape.lineTo(-0.008, 0.24); bladeShape.lineTo(-0.012, 0.02); bladeShape.closePath()
  const geo = new THREE.ExtrudeGeometry(bladeShape, { depth: 0.008, bevelEnabled: true, bevelThickness: 0.002, bevelSize: 0.002, bevelSegments: 1 })
  const blade = new THREE.Mesh(geo, steel); blade.rotation.x = -Math.PI / 2; g.add(blade)
  const edgeMesh = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.002, 0.3), edge)
  edgeMesh.position.set(0.014, 0, 0.17); g.add(edgeMesh)
  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.026, 0.12), handle)
  grip.position.set(0, 0, -0.07); g.add(grip)
  const guard = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.008, 0.014), steel)
  guard.position.set(0, 0, 0.002); g.add(guard)
  g.rotation.set(0.1, -0.35, -0.2)
  return g
}

export class WeaponSystem {
  constructor(renderer, audio, environment) {
    this.renderer = renderer
    this.audio = audio
    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(75, 1, 0.01, 5)
    this.scene.environment = environment
    this.scene.environmentIntensity = 0.5
    const hemi = new THREE.HemisphereLight(0x8db4d2, 0x1a1612, 1.5)
    this.scene.add(hemi)
    const key = new THREE.DirectionalLight(0xffd7b2, 2.6)
    key.position.set(1.5, 2.4, 1.2)
    this.scene.add(key)
    const rim = new THREE.DirectionalLight(0x6fb7e0, 1.4)
    rim.position.set(-2, 0.4, -1)
    this.scene.add(rim)
    const bounce = new THREE.PointLight(0xff8844, 2, 3, 2)
    bounce.position.set(1, -1, 0.5)
    this.scene.add(bounce)

    this.models = [buildRifle(), buildPistol()]
    this.knife = buildKnife()
    this.knife.position.set(0.3, -0.28, -0.4)
    this.knife.visible = false
    for (const m of this.models) this.scene.add(m)
    this.scene.add(this.knife)

    this.ammo = WEAPONS.map(w => w.magSize)
    this.reserve = [210, 90]
    this.index = 0
    this.fireTimer = 0
    this.reloadT = 0
    this.reloading = false
    this.reloadStage = 0
    this.switchT = 0
    this.switching = false
    this.pendingIndex = 0
    this.adsHeld = false
    this.adsAmount = 0
    this.triggerHeld = false
    this.shotThisFrame = false
    this.meleeT = 0
    this.meleeCooldown = 0
    this.meleeDidHit = false
    this.kick = 0
    this.kickVel = 0
    this.yawKick = 0
    this.swayX = 0
    this.swayY = 0
    this.swayTargetX = 0
    this.swayTargetY = 0
    this.bobPhase = 0
    this.recoilPitch = 0
    this.recoilYaw = 0
    this.shotsFired = 0
    this.shotsHit = 0
    this.muzzleTime = 0
    this.currentFov = 75
    this.baseFov = 75
    this.sprint = 0
    this.lastShotTime = -1
    this.landKick = 0
    this.visible = true
    this.models[0].position.set(0.205, -0.235, -0.52)
    this.models[1].position.set(0.2, -0.245, -0.5)
    this.models[0].rotation.set(0.02, -0.025, 0.015)
    this.models[1].rotation.set(0.02, -0.03, 0.015)
    this.models[1].scale.setScalar(0.94)
    this.magDrop = 0
    this.leftHandOffset = new THREE.Vector3()
    this.deathDrop = 0
  }

  get def() { return WEAPONS[this.index] }
  get mag() { return this.ammo[this.index] }
  get reserveAmmo() { return this.reserve[this.index] }

  setAspect(aspect) {
    this.camera.aspect = aspect
    this.camera.updateProjectionMatrix()
  }

  triggerDown() {
    if (this.switching || this.reloading) return
    this.triggerHeld = true
    if (!this.def.auto) this.tryFire()
  }
  triggerUp() { this.triggerHeld = false }

  setAds(v) { this.adsHeld = v }

  reload() {
    if (this.reloading || this.switching) return false
    if (this.mag >= this.def.magSize || this.reserveAmmo <= 0) return false
    this.reloading = true
    this.reloadT = 0
    this.reloadStage = 0
    this.audio.reloadStep(0)
    return true
  }

  switchTo(i) {
    if (i === this.index || this.switching) return false
    if (i < 0 || i >= WEAPONS.length) return false
    this.switching = true
    this.switchT = 0
    this.pendingIndex = i
    this.reloading = false
    return true
  }

  nextWeapon() { return this.switchTo((this.index + 1) % WEAPONS.length) }

  tryFire() {
    if (this.reloading || this.switching || this.meleeT > 0) return false
    if (this.fireTimer > 0) return false
    const def = this.def
    if (this.ammo[this.index] <= 0) {
      this.audio.dryFire()
      this.fireTimer = 0.25
      this.reload()
      return false
    }
    this.ammo[this.index]--
    this.fireTimer = 60 / def.rpm
    this.shotsFired++
    this.shotThisFrame = true
    this.lastShotTime = performance.now() / 1000
    const ads = this.adsAmount
    const kickScale = ads > 0.5 ? 0.72 : 1
    this.kick = 1
    this.kickVel = 2.6
    this.yawKick = rand(-1, 1) * (ads > 0.5 ? 0.35 : 1)
    this.recoilPitch += def.recoil * kickScale
    this.recoilYaw += this.yawKick * def.recoilYaw
    this.muzzleTime = 0.05
    this.audio.shot(def.kind)
    return true
  }

  melee() {
    if (this.meleeCooldown > 0 || this.switching || this.reloading) return false
    this.meleeT = 0.5
    this.meleeCooldown = 0.9
    this.meleeDidHit = false
    this.audio.melee()
    return true
  }

  consumeMeleeHit() {
    if (this.meleeT > 0 && this.meleeT < 0.34 && !this.meleeDidHit) {
      this.meleeDidHit = true
      return true
    }
    return false
  }

  update(dt, input) {
    this.shotThisFrame = false
    this.triggerHeld = input.fireHeld
    this.fireTimer = Math.max(0, this.fireTimer - dt)
    this.meleeCooldown = Math.max(0, this.meleeCooldown - dt)
    this.muzzleTime = Math.max(0, this.muzzleTime - dt)
    this.landKick = Math.max(0, this.landKick - dt * 3)

    const def = this.def
    const canAds = !this.reloading && !this.switching && this.meleeT <= 0 && !input.sprinting
    const targetAds = this.adsHeld && canAds ? 1 : 0
    this.adsAmount = damp(this.adsAmount, targetAds, 12, dt)
    this.sprint = damp(this.sprint, input.sprinting ? 1 : 0, 9, dt)

    this.kickVel += (-this.kick * 150 - this.kickVel * 16) * dt
    this.kick += this.kickVel * dt
    this.kick = clamp(this.kick, 0, 1.6)
    this.yawKick = damp(this.yawKick, 0, 8, dt)
    this.swayTargetX = clamp(input.mouseDX * 0.00016, -0.03, 0.03)
    this.swayTargetY = clamp(input.mouseDY * 0.00016, -0.03, 0.03)
    this.swayX = damp(this.swayX, this.swayTargetX, 9, dt)
    this.swayY = damp(this.swayY, this.swayTargetY, 9, dt)

    const speedFactor = clamp(input.speed / 7, 0, 1.4)
    this.bobPhase += dt * (input.sprinting ? 12.5 : 8.2) * Math.min(1, speedFactor + 0.25)
    const bobAmp = speedFactor * (1 - this.adsAmount * 0.82) * (input.grounded ? 1 : 0.3)
    const bobX = Math.sin(this.bobPhase) * 0.009 * bobAmp
    const bobY = Math.abs(Math.cos(this.bobPhase)) * 0.008 * bobAmp

    // firing
    if (input.fireHeld && !this.switching && !this.reloading && this.meleeT <= 0) {
      if (def.auto) this.tryFire()
      else if (!this.lastTrigger) this.tryFire()
    }
    this.lastTrigger = input.fireHeld
    if (input.fireHeld && this.ammo[this.index] === 0 && !this.reloading && !this.switching) this.reload()

    // reload timeline
    if (this.reloading) {
      this.reloadT += dt
      const t = this.reloadT / def.reloadTime
      if (t > 0.18 && this.reloadStage === 0) { this.reloadStage = 1; this.audio.reloadStep(1) }
      if (t > 0.66 && this.reloadStage === 1) { this.reloadStage = 2; this.audio.reloadStep(2) }
      if (t > 0.86 && this.reloadStage === 2) { this.reloadStage = 3; this.audio.reloadStep(3) }
      if (t >= 1) {
        const need = def.magSize - this.ammo[this.index]
        const take = Math.min(need, this.reserveAmmo)
        this.ammo[this.index] += take
        this.reserve[this.index] -= take
        this.reloading = false
        this.reloadStage = 0
        this.reloadT = 0
      }
    }

    // switching
    if (this.switching) {
      this.switchT += dt
      if (this.switchT > 0.24 && this.pendingIndex !== this.index) {
        this.index = this.pendingIndex
        this.audio.reloadStep(3)
      }
      if (this.switchT > 0.56) { this.switching = false; this.switchT = 0 }
    }

    if (this.meleeT > 0) this.meleeT = Math.max(0, this.meleeT - dt)
    if (this.meleeT > 0.26) this.knife.visible = true
    else this.knife.visible = false

    // model placement
    for (let i = 0; i < this.models.length; i++) {
      const model = this.models[i]
      model.visible = i === this.index && this.visible
      if (!model.visible) continue
      const isRifle = i === 0
      const hip = isRifle ? new THREE.Vector3(0.205, -0.235, -0.52) : new THREE.Vector3(0.2, -0.245, -0.5)
      const ads = isRifle ? new THREE.Vector3(0, -0.072, -0.435) : new THREE.Vector3(0, -0.077, -0.4)
      const base = hip.clone().lerp(ads, this.adsAmount)
      const reloadCurve = this.reloading ? Math.sin(clamp(this.reloadT / def.reloadTime, 0, 1) * Math.PI) : 0
      const switchCurve = this.switching ? Math.sin(clamp(this.switchT / 0.56, 0, 1) * Math.PI) : 0
      const k = this.kick
      base.x += this.swayX * (1 - this.adsAmount * 0.8) + bobX + (this.adsAmount < 0.5 ? this.sprint * 0.025 : 0)
      base.y += this.swayY * (1 - this.adsAmount * 0.8) - bobY - reloadCurve * 0.055 - switchCurve * 0.28 + this.sprint * -0.025 - this.landKick * 0.02
      base.z += k * 0.055 + reloadCurve * 0.02
      model.position.copy(base)
      const recoilTilt = k * 0.055
      const rotX = (isRifle ? 0.02 : 0.02) + this.swayY * 0.6 + recoilTilt + reloadCurve * -0.5 + switchCurve * 0.35
      const rotY = (isRifle ? -0.025 : -0.03) * (1 - this.adsAmount) + this.swayX * 0.8 + this.yawKick * 0.018
      const rotZ = 0.015 + this.swayX * 0.9 + reloadCurve * -0.6 + this.sprint * -0.16 + switchCurve * 0.8
      model.rotation.set(rotX, rotY, rotZ)

      const ud = model.userData
      if (ud.mag) {
        const md = this.reloading ? Math.max(0, Math.sin(clamp((this.reloadT / def.reloadTime - 0.12) / 0.52, 0, 1) * Math.PI)) : 0
        ud.mag.position.y = ud.magBaseY - md * 0.24
        ud.mag.rotation.z = md * 0.5
      }
      if (ud.leftHand) {
        const lh = this.reloading ? Math.sin(clamp(this.reloadT / def.reloadTime, 0, 1) * Math.PI) : 0
        ud.leftHand.position.y = -0.09 - lh * 0.08
        ud.leftHand.position.z = -0.38 + lh * 0.26
      }
      if (ud.flash) {
        ud.flash.material.opacity = this.muzzleTime > 0 ? rand(0.7, 1) : 0
        ud.flash.material.rotation = rand(0, 6.28)
        ud.flash.scale.setScalar(rand(0.28, 0.42))
      }
      if (ud.flashLight) ud.flashLight.intensity = this.muzzleTime > 0 ? 3 : 0
      if (ud.dot) {
        const target = this.adsAmount > 0.65 ? 0.014 : 0.01
        ud.dot.scale.setScalar(damp(ud.dot.scale.x, target, 8, dt))
        ud.dot.material.opacity = this.adsAmount > 0.5 ? 0.95 : 0.55
      }
    }

    // knife slash
    if (this.knife.visible) {
      const t = 1 - this.meleeT / 0.5
      const slash = Math.sin(t * Math.PI)
      this.knife.position.set(0.3 - slash * 0.45, -0.26 + slash * 0.08, -0.38 - slash * 0.15)
      this.knife.rotation.set(0.1 + slash * 0.6, -0.35 - slash * 0.8, -0.2 + slash * 1.6)
      this.knife.scale.setScalar(1)
    }

    // fov
    this.currentFov = lerp(this.baseFov, def.adsFov, this.adsAmount)
    this.camera.fov = this.currentFov
    this.camera.updateProjectionMatrix()
  }

  getSpread(moving) {
    const def = this.def
    const base = lerp(def.spreadHip, def.spreadAds, this.adsAmount)
    const move = this.adsAmount > 0.5 ? 0.002 : 0.014
    return base + (moving ? move : 0) + Math.min(0.02, this.kick * 0.004)
  }

  consumeRecoil() {
    const p = this.recoilPitch
    const y = this.recoilYaw
    this.recoilPitch = 0
    this.recoilYaw = 0
    return { pitch: p, yaw: y }
  }

  getState() {
    const def = this.def
    return {
      name: def.name, short: def.short, mode: def.mode, mag: this.ammo[this.index], reserve: this.reserve[this.index],
      reloading: this.reloading, reloadProgress: this.reloading ? clamp(this.reloadT / def.reloadTime, 0, 1) : 0,
      ads: this.adsAmount, switching: this.switching, index: this.index, melee: this.meleeT > 0,
      maxMag: def.magSize,
    }
  }

  addAmmo(frac = 0.5) {
    for (let i = 0; i < this.reserve.length; i++) {
      this.reserve[i] = Math.min(WEAPONS[i].reserveMax, this.reserve[i] + Math.ceil(WEAPONS[i].reserveMax * frac))
    }
    this.ammo[this.index] = Math.min(WEAPONS[this.index].magSize, this.ammo[this.index] + Math.ceil(WEAPONS[this.index].magSize * 0.5))
  }
}

const pad = (n, l = 2) => String(Math.max(0, Math.floor(n))).padStart(l, '0')

export class HUD {
  constructor() {
    this.el = {
      hud: document.getElementById('hud'),
      healthFill: document.getElementById('health-fill'),
      healthValue: document.getElementById('health-value'),
      armorFill: document.getElementById('armor-fill'),
      armorValue: document.getElementById('armor-value'),
      healthWrap: document.querySelector('.health-wrap'),
      healthBar: document.querySelector('.health-bar'),
      ammoMag: document.getElementById('ammo-mag'),
      ammoReserve: document.getElementById('ammo-reserve'),
      weaponName: document.getElementById('weapon-name'),
      fireMode: document.getElementById('fire-mode'),
      reloadFill: document.getElementById('reload-fill'),
      grenadeCount: document.getElementById('grenade-count'),
      tGrenades: document.getElementById('t-grenades'),
      waveLabel: document.getElementById('wave-label'),
      enemyCount: document.getElementById('enemy-count'),
      objective: document.getElementById('objective-text'),
      score: document.getElementById('score'),
      combo: document.getElementById('combo'),
      compass: document.getElementById('compass-strip'),
      crosshair: document.getElementById('crosshair'),
      hitmarker: document.getElementById('hitmarker'),
      killfeed: document.getElementById('killfeed'),
      minimap: document.getElementById('minimap'),
      bossBar: document.getElementById('boss-bar'),
      bossName: document.getElementById('boss-name'),
      bossFill: document.getElementById('boss-fill'),
      bossHp: document.getElementById('boss-hp'),
      damageFlash: document.getElementById('damage-flash'),
      lowHealth: document.getElementById('low-health'),
      damageDirs: document.getElementById('damage-dirs'),
      banner: document.getElementById('wave-banner'),
      bannerTitle: document.getElementById('banner-title'),
      bannerSub: document.getElementById('banner-sub'),
      notification: document.getElementById('notification'),
      status: document.getElementById('status-text'),
      slots: [...document.querySelectorAll('.weapon-slots .slot')],
      reticleHint: document.getElementById('reticle-hint'),
      pause: document.getElementById('pause'),
      pauseWave: document.getElementById('pause-wave'),
      pauseKills: document.getElementById('pause-kills'),
      pauseScore: document.getElementById('pause-score'),
      results: document.getElementById('results'),
      resultKicker: document.getElementById('result-kicker'),
      resultTitle: document.getElementById('result-title'),
      resultSub: document.getElementById('result-sub'),
      resultWave: document.getElementById('result-wave'),
      resultKills: document.getElementById('result-kills'),
      resultAcc: document.getElementById('result-acc'),
      resultScore: document.getElementById('result-score'),
      resultBest: document.getElementById('result-best'),
      resultTime: document.getElementById('result-time'),
      bestScore: document.getElementById('best-score'),
      menu: document.getElementById('menu'),
      touch: document.getElementById('touch'),
      boot: document.getElementById('boot'),
      interact: document.getElementById('interact-prompt'),
    }
    this.ctx = this.el.minimap.getContext('2d')
    this.cache = {}
    this.dirEls = []
    for (let i = 0; i < 4; i++) {
      const d = document.createElement('div')
      d.className = 'dmg-dir'
      this.el.damageDirs.appendChild(d)
      this.dirEls.push(d)
    }
    this.dirIndex = 0
    this.buildCompass()
    this.bannerTimer = null
    this.notifTimer = null
    this.flashTimer = null
    this.lowPulse = false
    this.killTimes = []
    this.best = Number(localStorage.getItem('zerohour.best') || 0)
    this.setBest(this.best)
  }

  setBest(v) {
    this.best = v
    this.el.bestScore.textContent = `BEST SCORE — ${pad(v, 6)}`
  }

  buildCompass() {
    const strip = this.el.compass
    strip.innerHTML = ''
    const pxPerDeg = 2.6
    const cards = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' }
    for (let deg = -360; deg <= 720; deg += 5) {
      const x = (deg + 360) * pxPerDeg
      const tick = document.createElement('i')
      const isMajor = deg % 45 === 0
      tick.className = 'comp-tick' + (isMajor ? ' major' : '')
      tick.style.left = x + 'px'
      strip.appendChild(tick)
      if (isMajor) {
        const label = document.createElement('span')
        label.className = 'comp-label' + ([0, 90, 180, 270].includes(((deg % 360) + 360) % 360) ? ' card' : '')
        label.style.left = x + 'px'
        label.textContent = cards[((deg % 360) + 360) % 360]
        strip.appendChild(label)
      } else if (deg % 15 === 0) {
        const dot = document.createElement('span')
        dot.className = 'comp-tick major'
        dot.style.left = (x + 1) + 'px'
        dot.style.height = '3px'
        dot.style.opacity = '.7'
        strip.appendChild(dot)
      }
    }
    this.pxPerDeg = pxPerDeg
    this.compassWidth = strip.parentElement.clientWidth || 420
  }

  updateHeading(deg) {
    const w = this.el.compass.parentElement.clientWidth
    if (w !== this.compassWidth) { this.compassWidth = w }
    const center = w / 2
    const x = center - (deg + 360) * this.pxPerDeg
    this.el.compass.style.transform = `translateX(${x}px)`
  }

  setHudVisible(v) { this.el.hud.classList.toggle('hidden', !v) }
  setMenuVisible(v) { this.el.menu.classList.toggle('hidden', !v) }
  setTouchVisible(v) { this.el.touch.classList.toggle('hidden', !v) }

  bootDone() {
    this.el.boot.classList.add('done')
    setTimeout(() => this.el.boot.classList.add('hidden'), 650)
  }

  showError(msg) {
    document.getElementById('error-screen').classList.remove('hidden')
    document.getElementById('error-text').textContent = msg
    this.el.boot.classList.add('hidden')
  }

  update(dt, state) {
    const c = this.cache
    const s = state
    const hp = Math.ceil(s.health), ar = Math.ceil(s.armor)
    if (c.hp !== hp) {
      c.hp = hp
      this.el.healthValue.textContent = hp
      this.el.healthFill.style.width = Math.max(0, Math.min(100, hp)) + '%'
      this.el.healthBar.classList.toggle('low', hp <= 34)
    }
    if (c.ar !== ar) {
      c.ar = ar
      this.el.armorValue.textContent = ar
      this.el.armorFill.style.width = Math.max(0, Math.min(100, ar / 1.5)) + '%'
    }
    const ws = s.weapon
    if (c.mag !== ws.mag || c.reserve !== ws.reserve) {
      c.mag = ws.mag; c.reserve = ws.reserve
      this.el.ammoMag.textContent = pad(ws.mag, 2)
      this.el.ammoReserve.textContent = pad(ws.reserve, 3)
      this.el.ammoMag.style.color = ws.mag <= Math.ceil(ws.maxMag * 0.25) ? '#ff9b84' : ''
    }
    if (c.wname !== ws.name) { c.wname = ws.name; this.el.weaponName.textContent = ws.name; this.el.fireMode.textContent = ws.mode }
    if (c.widx !== ws.index) {
      c.widx = ws.index
      this.el.slots.forEach((s2, i) => s2.classList.toggle('active', i === ws.index))
    }
    const rp = ws.reloading ? Math.round(ws.reloadProgress * 100) : 0
    if (c.rp !== rp) { c.rp = rp; this.el.reloadFill.style.width = rp + '%' }
    if (c.gren !== s.grenades) { c.gren = s.grenades; this.el.grenadeCount.textContent = pad(s.grenades, 2); if (this.el.tGrenades) this.el.tGrenades.textContent = s.grenades }

    if (c.wave !== s.wave || c.left !== s.enemiesLeft) {
      c.wave = s.wave; c.left = s.enemiesLeft
      this.el.waveLabel.textContent = `WAVE ${pad(s.wave)} / ${pad(s.totalWaves)}`
      this.el.enemyCount.textContent = s.enemiesLeft === 1 ? '1 HOSTILE' : `${s.enemiesLeft} HOSTILES`
    }
    if (c.objective !== s.objective) { c.objective = s.objective; this.el.objective.textContent = s.objective }
    if (c.score !== s.score) {
      c.score = s.score
      this.el.score.textContent = pad(s.score, 6)
    }
    if (c.combo !== s.combo) {
      c.combo = s.combo
      this.el.combo.textContent = s.combo > 1 ? `×${s.combo} MULTI-KILL` : ''
      this.el.combo.classList.toggle('show', s.combo > 1)
    }
    const spread = 5 + s.spread * 900
    if (Math.abs((c.spread || 0) - spread) > 0.5) { c.spread = spread; this.el.crosshair.style.setProperty('--spread', spread.toFixed(1) + 'px') }
    const ads = s.weapon.ads > 0.55
    if (c.ads !== ads) { c.ads = ads; this.el.crosshair.classList.toggle('ads', ads) }

    const status = hp <= 30 ? 'CRITICAL' : ws.reloading ? 'RELOADING' : s.enemiesLeft > 0 ? 'ENGAGED' : 'STANDBY'
    if (c.status !== status) {
      c.status = status
      this.el.status.innerHTML = `<i></i>${status}`
      this.el.status.classList.toggle('hurt', hp <= 30)
    }

    this.updateHeading(s.heading)
    this.drawMinimap(s)
    this.updateBoss(s.boss)
    this.updateLowHealth(hp)
  }

  updateLowHealth(hp) {
    const low = hp <= 35
    this.el.lowHealth.style.opacity = low ? String(0.5 + (35 - hp) / 70) : '0'
    if (low !== this.lowPulse) {
      this.lowPulse = low
      this.el.lowHealth.classList.toggle('pulse', low)
    }
  }

  drawMinimap(s) {
    const ctx = this.ctx
    const W = 200
    const { staticMap, mapScale } = s.world
    ctx.clearRect(0, 0, W, W)
    ctx.drawImage(staticMap, 0, 0, W, W)
    // radar sweep
    ctx.save()
    ctx.translate(100, 100)
    ctx.rotate((performance.now() / 1000) * 1.1)
    const grad = ctx.createLinearGradient(0, 0, 100, 0)
    grad.addColorStop(0, 'rgba(120,220,240,0)')
    grad.addColorStop(1, 'rgba(120,220,240,.11)')
    ctx.fillStyle = grad
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, 98, -0.55, 0); ctx.closePath(); ctx.fill()
    ctx.restore()

    const toPx = (v) => (v + 40) / 80 * W
    // pickups
    for (const p of s.pickups) {
      ctx.fillStyle = p.type === 'health' ? 'rgba(130,240,170,.95)' : p.type === 'armor' ? 'rgba(120,200,255,.95)' : 'rgba(255,190,90,.95)'
      ctx.beginPath(); ctx.arc(toPx(p.x), toPx(p.z), 2, 0, 7); ctx.fill()
    }
    // enemies
    for (const e of s.enemies) {
      if (e.dead) continue
      const x = toPx(e.x), y = toPx(e.z)
      const dist = Math.hypot(x - 100, y - 100)
      if (dist > 96) continue
      ctx.fillStyle = e.boss ? 'rgba(255,70,50,1)' : e.alerted ? 'rgba(255,100,70,.95)' : 'rgba(255,150,100,.6)'
      ctx.beginPath(); ctx.arc(x, y, e.boss ? 4 : 2.5, 0, 7); ctx.fill()
      if (e.alerted) { ctx.strokeStyle = 'rgba(255,80,50,.28)'; ctx.beginPath(); ctx.arc(x, y, 5.5, 0, 7); ctx.stroke() }
    }
    // player
    const px = toPx(s.player.x), py = toPx(s.player.z)
    ctx.save()
    ctx.translate(px, py)
    ctx.rotate(s.yaw)
    ctx.fillStyle = 'rgba(130,230,255,1)'
    ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(4.5, 5); ctx.lineTo(0, 2.8); ctx.lineTo(-4.5, 5); ctx.closePath(); ctx.fill()
    ctx.strokeStyle = 'rgba(130,230,255,.22)'
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -20); ctx.stroke()
    ctx.restore()
    // border cross
    ctx.strokeStyle = 'rgba(120,200,220,.16)'
    ctx.beginPath(); ctx.moveTo(100, 0); ctx.lineTo(100, 200); ctx.moveTo(0, 100); ctx.lineTo(200, 100); ctx.stroke()
  }

  updateBoss(boss) {
    if (!boss) {
      if (this.cache.boss !== false) { this.el.bossBar.classList.add('hidden'); this.cache.boss = false }
      return
    }
    this.el.bossBar.classList.remove('hidden')
    this.cache.boss = true
    this.el.bossName.textContent = boss.name
    this.el.bossFill.style.width = Math.max(0, boss.hp / boss.max * 100) + '%'
    this.el.bossHp.textContent = Math.ceil(boss.hp / boss.max * 100) + '%'
  }

  hit(kind = 'body') {
    const hm = this.el.hitmarker
    hm.classList.remove('show', 'kill', 'head')
    hm.classList.add('show')
    if (kind === 'kill') hm.classList.add('kill')
    if (kind === 'head') hm.classList.add('head')
    // force reflow for repeated hits
    void hm.offsetWidth
  }

  addKill(weapon, head = false, boss = false) {
    const item = document.createElement('div')
    item.className = 'kill-item' + (head ? ' head' : '')
    item.innerHTML = `<b>RAVEN</b> ${boss ? '<em>// WARDEN</em> ' : ''}${head ? '<em>HEADSHOT</em> ' : ''}${weapon}`
    this.el.killfeed.prepend(item)
    while (this.el.killfeed.children.length > 5) this.el.killfeed.lastChild.remove()
    setTimeout(() => { item.style.opacity = '0'; item.style.transition = 'opacity .4s'; setTimeout(() => item.remove(), 420) }, 4200)
  }

  damage(amount, angle) {
    this.el.damageFlash.style.opacity = String(Math.min(0.85, 0.25 + amount / 70))
    clearTimeout(this.flashTimer)
    this.flashTimer = setTimeout(() => { this.el.damageFlash.style.opacity = '0' }, 130)
    if (angle !== undefined) {
      const d = this.dirEls[this.dirIndex++ % this.dirEls.length]
      d.classList.remove('show')
      void d.offsetWidth
      d.style.setProperty('--rot', angle + 'rad')
      d.classList.add('show')
    }
  }

  showBanner(title, sub, kicker = 'INCOMING') {
    this.el.banner.querySelector('.banner-kicker').textContent = kicker
    this.el.bannerTitle.textContent = title
    this.el.bannerSub.textContent = sub
    this.el.banner.classList.remove('hidden', 'show')
    void this.el.banner.offsetWidth
    this.el.banner.classList.add('show')
    clearTimeout(this.bannerTimer)
    this.bannerTimer = setTimeout(() => this.el.banner.classList.add('hidden'), 2700)
  }

  notify(text, duration = 2200) {
    this.el.notification.innerHTML = text
    this.el.notification.classList.add('show')
    clearTimeout(this.notifTimer)
    this.notifTimer = setTimeout(() => this.el.notification.classList.remove('show'), duration)
  }

  prompt(text) {
    if (!text) { this.el.interact.classList.add('hidden'); return }
    this.el.interact.classList.remove('hidden')
    this.el.interact.innerHTML = text
  }

  showPause(show, state) {
    this.el.pause.classList.toggle('hidden', !show)
    if (show && state) {
      this.el.pauseWave.textContent = pad(state.wave)
      this.el.pauseKills.textContent = pad(state.kills)
      this.el.pauseScore.textContent = pad(state.score, 6)
    }
  }

  showResults(win, state) {
    this.el.results.classList.remove('hidden')
    this.el.resultKicker.textContent = win ? 'MISSION COMPLETE' : 'MISSION FAILED'
    this.el.resultTitle.textContent = win ? 'SECTOR SECURED' : 'OPERATOR DOWN'
    this.el.resultSub.textContent = win ? 'Kilo-7 is quiet. For now.' : 'The line broke. Hold it longer next time.'
    this.el.resultWave.textContent = pad(state.wave, 2)
    this.el.resultKills.textContent = pad(state.kills, 2)
    this.el.resultAcc.textContent = state.accuracy + '%'
    this.el.resultScore.textContent = pad(state.score, 6)
    this.el.resultBest.textContent = pad(state.best, 6)
    this.el.resultTime.textContent = state.time
  }

  hideResults() { this.el.results.classList.add('hidden') }

  setReticleHint(v) { this.el.reticleHint.classList.toggle('hidden', !v) }

  setSoundMuted(m) {
    document.querySelectorAll('#btn-sound, #btn-menu-sound').forEach(b => b.classList.toggle('muted', m))
    localStorage.setItem('zerohour.muted', m ? '1' : '0')
  }
}

import * as THREE from 'three'
import { spriteTexture } from './textures.js'

const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const damp = (a, b, l, dt) => a + (b - a) * (1 - Math.exp(-l * dt))
const TAU = Math.PI * 2

export const ENEMY_TYPES = {
  grunt: {
    name: 'GRUNT', hp: 100, speed: 2.65, scale: 1, damage: 8, accuracy: 0.42,
    rangeMin: 9, rangeMax: 24, burst: [3, 5], burstGap: 0.13, fireGap: [1.7, 2.8],
    score: 100, drop: 0.3, eye: 0x74d8ff, cloth: 0x394137, vest: 0x181d1a, plate: 0x242a26,
  },
  rusher: {
    name: 'RUSHER', hp: 70, speed: 4.35, scale: 0.96, damage: 6, accuracy: 0.34,
    rangeMin: 4, rangeMax: 15, burst: [5, 8], burstGap: 0.085, fireGap: [1.3, 2.1],
    score: 125, drop: 0.22, eye: 0xff3c2c, cloth: 0x4a2c24, vest: 0x1d1715, plate: 0x2a1a16,
  },
  sniper: {
    name: 'MARKSMAN', hp: 80, speed: 2.1, scale: 1.02, damage: 22, accuracy: 0.78,
    rangeMin: 22, rangeMax: 34, burst: [1, 1], burstGap: 0.2, fireGap: [2.6, 3.8],
    score: 175, drop: 0.3, eye: 0x9cffb4, cloth: 0x27332a, vest: 0x161c17, plate: 0x1d241f, sniper: true,
  },
  heavy: {
    name: 'JUGGERNAUT', hp: 320, speed: 1.65, scale: 1.24, damage: 7, accuracy: 0.3,
    rangeMin: 8, rangeMax: 22, burst: [10, 16], burstGap: 0.075, fireGap: [1.5, 2.4],
    score: 350, drop: 1, eye: 0xff8a32, cloth: 0x32363a, vest: 0x141719, plate: 0x1d2225, heavy: true, boss: false,
  },
  boss: {
    name: 'WARDEN', hp: 1500, speed: 1.55, scale: 1.55, damage: 9, accuracy: 0.38,
    rangeMin: 8, rangeMax: 26, burst: [14, 20], burstGap: 0.065, fireGap: [1.1, 1.8],
    score: 1500, drop: 1, eye: 0xff1a0a, cloth: 0x232327, vest: 0x0c0d0f, plate: 0x16161a, heavy: true, boss: true,
  },
}

let cache = null
function materials() {
  if (cache) return cache
  cache = {
    glove: new THREE.MeshStandardMaterial({ color: 0x0d0f0e, roughness: 0.9 }),
    boot: new THREE.MeshStandardMaterial({ color: 0x0b0d0c, roughness: 0.82, metalness: 0.15 }),
    metal: new THREE.MeshStandardMaterial({ color: 0x1b2022, roughness: 0.45, metalness: 0.85 }),
    lens: new THREE.MeshBasicMaterial({ color: 0x182228 }),
    skin: new THREE.MeshStandardMaterial({ color: 0x4a3b30, roughness: 0.85 }),
  }
  return cache
}

function geoBox(w, h, d, mat, x, y, z, parent) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
  m.position.set(x, y, z)
  m.castShadow = true; m.receiveShadow = true
  parent.add(m)
  return m
}

function buildEnemyModel(type) {
  const cfg = ENEMY_TYPES[type]
  const M = materials()
  const root = new THREE.Group()
  const body = new THREE.Group()
  root.add(body)
  const cloth = new THREE.MeshStandardMaterial({ color: cfg.cloth, roughness: 0.88, metalness: 0.05 })
  const vest = new THREE.MeshStandardMaterial({ color: cfg.vest, roughness: 0.72, metalness: 0.18 })
  const plate = new THREE.MeshStandardMaterial({ color: cfg.plate, roughness: 0.55, metalness: 0.35 })
  const eye = new THREE.MeshStandardMaterial({ color: 0x050505, emissive: cfg.eye, emissiveIntensity: 2.8, roughness: 0.4 })
  const core = new THREE.MeshStandardMaterial({ color: 0x100302, emissive: 0xff2a10, emissiveIntensity: 3.6, roughness: 0.4 })

  // legs
  const legs = []
  for (const side of [-1, 1]) {
    const hip = new THREE.Group()
    hip.position.set(side * 0.14, 0.94, 0)
    geoBox(0.16, 0.43, 0.18, cloth, 0, -0.2, 0, hip)
    geoBox(0.14, 0.4, 0.16, cloth, 0, -0.59, 0, hip)
    geoBox(0.16, 0.13, 0.26, M.boot, 0, -0.84, -0.03, hip)
    geoBox(0.17, 0.12, 0.14, plate, 0, -0.3, -0.02, hip)
    body.add(hip)
    legs.push(hip)
  }
  // torso
  geoBox(0.5, 0.56, 0.3, cloth, 0, 1.27, 0, body)
  const vestMesh = geoBox(0.55, 0.46, 0.37, vest, 0, 1.28, -0.01, body)
  geoBox(0.5, 0.16, 0.39, plate, 0, 1.36, 0, body)
  for (let i = 0; i < 3; i++) geoBox(0.12, 0.13, 0.07, plate, -0.17 + i * 0.17, 1.1, -0.2, body)
  geoBox(0.16, 0.2, 0.09, vest, 0.32, 1.2, 0.12, body)
  // shoulder pads
  for (const side of [-1, 1]) {
    geoBox(0.2, 0.14, 0.3, plate, side * 0.31, 1.47, 0, body)
    geoBox(0.09, 0.2, 0.24, plate, side * 0.4, 1.37, 0, body)
  }
  // backpack
  geoBox(0.36, 0.4, 0.18, vest, 0, 1.3, 0.22, body)
  // head
  const head = new THREE.Group()
  head.position.set(0, 1.68, 0)
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.145, 12, 10), M.skin)
  skull.scale.set(0.94, 1.05, 0.95); skull.castShadow = true
  head.add(skull)
  geoBox(0.25, 0.12, 0.28, vest, 0, 0.02, 0.02, head)
  // helmet
  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.185, 14, 10, 0, TAU, 0, Math.PI * 0.6), plate)
  helmet.position.y = 0.055
  helmet.castShadow = true
  head.add(helmet)
  geoBox(0.3, 0.045, 0.34, plate, 0, 0.01, 0, head)
  const visor = geoBox(0.21, 0.045, 0.02, eye, 0, -0.01, -0.155, head)
  geoBox(0.06, 0.08, 0.05, plate, -0.17, 0.03, 0, head)
  body.add(head)

  // arms
  const arms = []
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group()
    shoulder.position.set(side * 0.33, 1.46, 0)
    geoBox(0.14, 0.34, 0.16, cloth, 0, -0.17, 0, shoulder)
    const fore = new THREE.Group(); fore.position.set(0, -0.36, 0)
    geoBox(0.12, 0.32, 0.14, cloth, 0, -0.14, 0, fore)
    const hand = geoBox(0.12, 0.12, 0.16, M.glove, 0, -0.32, -0.02, fore)
    shoulder.add(fore)
    body.add(shoulder)
    arms.push({ shoulder, fore, hand })
  }
  // weapon
  const weapon = new THREE.Group()
  weapon.position.set(0.16, 1.23, -0.23)
  const gunMat = M.metal
  if (cfg.heavy) {
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.5, 10), gunMat)
    barrel.rotation.x = Math.PI / 2; barrel.position.z = -0.28; weapon.add(barrel)
    for (let i = 0; i < 5; i++) {
      const b = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.55, 6), gunMat)
      b.rotation.x = Math.PI / 2; b.position.set(Math.cos(i / 5 * TAU) * 0.045, Math.sin(i / 5 * TAU) * 0.045, -0.35)
      weapon.add(b)
    }
    geoBox(0.2, 0.2, 0.36, gunMat, 0, 0, 0.05, weapon)
    geoBox(0.08, 0.12, 0.14, vest, 0, -0.14, 0.12, weapon)
  } else {
    geoBox(0.075, 0.09, 0.4, gunMat, 0, 0, -0.1, weapon)
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, cfg.sniper ? 0.55 : 0.3, 8), gunMat)
    barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.01, cfg.sniper ? -0.55 : -0.42); weapon.add(barrel)
    geoBox(0.05, 0.13, 0.08, vest, 0, -0.1, -0.04, weapon)
    geoBox(0.04, 0.05, 0.22, vest, 0, -0.01, 0.16, weapon)
    if (cfg.sniper) {
      const scope = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.2, 10), gunMat)
      scope.rotation.x = Math.PI / 2; scope.position.set(0, 0.08, -0.12); weapon.add(scope)
    }
  }
  body.add(weapon)
  // arms aiming pose
  arms[0].shoulder.rotation.set(-1.1, 0, 0.22)
  arms[0].fore.rotation.set(0.2, 0, 0)
  arms[1].shoulder.rotation.set(-1.25, 0, -0.55)
  arms[1].fore.rotation.set(0.45, 0, 0.2)

  if (cfg.boss) {
    // armor mantle
    for (const side of [-1, 1]) {
      geoBox(0.24, 0.38, 0.5, plate, side * 0.38, 1.42, 0.02, body)
    }
    geoBox(0.5, 0.16, 0.12, plate, 0, 1.62, -0.2, body)
    const coreMesh = new THREE.Mesh(new THREE.SphereGeometry(0.11, 12, 10), core)
    coreMesh.position.set(0, 1.25, -0.235)
    body.add(coreMesh)
    // chest spikes
    for (const side of [-1, 1]) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.18, 5), plate)
      spike.position.set(side * 0.24, 1.52, -0.2); spike.rotation.x = -0.3
      body.add(spike)
    }
    head.scale.setScalar(1.12)
  }

  // hitboxes (invisible)
  const hitMat = new THREE.MeshBasicMaterial({ visible: false })
  const headHit = new THREE.Mesh(new THREE.SphereGeometry(0.2, 8, 6), hitMat)
  headHit.position.set(0, 1.72, 0)
  const bodyHit = new THREE.Mesh(new THREE.BoxGeometry(0.58, 0.65, 0.42), hitMat)
  bodyHit.position.set(0, 1.26, 0)
  const legsHit = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.88, 0.32), hitMat)
  legsHit.position.set(0, 0.52, 0)
  root.add(headHit, bodyHit, legsHit)
  let coreHit = null
  if (cfg.boss) {
    coreHit = new THREE.Mesh(new THREE.SphereGeometry(0.15, 8, 6), hitMat)
    coreHit.position.set(0, 1.25, -0.25)
    root.add(coreHit)
  }

  const muzzle = new THREE.Object3D()
  muzzle.position.set(0, 0.01, cfg.sniper ? -0.86 : cfg.heavy ? -0.62 : -0.68)
  weapon.add(muzzle)

  root.scale.setScalar(cfg.scale)
  return { root, body, head, legs, arms, weapon, muzzle, hitMeshes: [headHit, bodyHit, legsHit, ...(coreHit ? [coreHit] : [])], coreMesh: cfg.boss ? body.children.find(c => c.geometry?.type === 'SphereGeometry' && c.material === core) : null, headHit, bodyHit, legsHit, coreHit, visor }
}

function disposeGroup(group) {
  group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.() })
}

export class EnemySystem {
  constructor(scene, world, effects, audio) {
    this.scene = scene
    this.world = world
    this.effects = effects
    this.audio = audio
    this.enemies = []
    this.projectiles = []
    this.raycaster = new THREE.Raycaster()
    this.raycaster.far = 160
    this.tmp = new THREE.Vector3()
    this.tmp2 = new THREE.Vector3()
    this.losTimer = 0
    this.onPlayerDamage = null
    this.onKill = null
    this.onBossHit = null
    this.healthBarsVisible = false
  }

  spawn(type, pos, { banner = false } = {}) {
    const cfg = ENEMY_TYPES[type]
    const model = buildEnemyModel(type)
    const root = model.root
    const y = this.world.groundHeightAt(pos.x, pos.z)
    root.position.set(pos.x, y, pos.z)
    this.scene.add(root)
    model.hitMeshes.forEach(h => { h.userData.enemy = null; h.userData.zone = h === model.headHit ? 'head' : h === model.legsHit ? 'limb' : h === model.coreHit ? 'core' : 'body' })
    const e = {
      type, cfg, ...model, root, health: cfg.hp, maxHealth: cfg.hp,
      alive: true, dead: false, deadT: 0, deathSign: Math.random() > 0.5 ? 1 : -1,
      state: 'combat', alerted: true, los: false, losTimer: rand(0, 0.25),
      fireTimer: rand(0.5, 1.8), burstLeft: 0, burstTimer: 0, aimTimer: 0, aiming: false,
      strafeDir: Math.random() > 0.5 ? 1 : -1, strafeTimer: rand(1.2, 3),
      repoTimer: rand(2, 5), coverTarget: null, walkPhase: rand(0, 6.28), moveSpeed: 0,
      spawnT: 0, flashT: 0, suppressT: 0, lastSeen: 0, muzzleGlow: 0, radius: 0.38,
      meleeTimer: 0, laser: null, rocketTimer: rand(4, 7), boss: cfg.boss, hitFlash: 0,
    }
    model.hitMeshes.forEach(h => { h.userData.enemy = e })
    e.laser = this.makeLaser()
    if (cfg.sniper) e.laser.visible = false
    this.enemies.push(e)
    // spawn flare
    for (let i = 0; i < 10; i++) {
      this.effects.smoke.spawn({
        pos: new THREE.Vector3(pos.x + rand(-0.5, 0.5), y + rand(0.2, 1.8), pos.z + rand(-0.5, 0.5)),
        vel: new THREE.Vector3(rand(-0.4, 0.4), rand(0.2, 0.8), rand(-0.4, 0.4)),
        color: [0.22, 0.2, 0.19], size: rand(0.4, 0.8), life: rand(0.8, 1.6), gravity: -0.2, drag: 0.94, grow: 0.8, alpha: 0.4,
      })
    }
    return e
  }

  makeLaser() {
    const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3(0, 0, -1)])
    const mat = new THREE.LineBasicMaterial({ color: 0xff2a1a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false })
    const line = new THREE.Line(geo, mat)
    line.frustumCulled = false
    this.scene.add(line)
    return line
  }

  aliveCount() { return this.enemies.reduce((n, e) => n + (e.dead ? 0 : 1), 0) }

  getBoss() {
    const b = this.enemies.find(e => e.boss && !e.dead)
    return b ? { name: b.cfg.name, hp: b.health, max: b.maxHealth } : null
  }

  hitMeshes() {
    const arr = []
    for (const e of this.enemies) if (!e.dead) arr.push(...e.hitMeshes)
    return arr
  }

  raycast(origin, dir, maxDist = 130) {
    this.raycaster.set(origin, dir)
    this.raycaster.far = maxDist
    const hits = this.raycaster.intersectObjects(this.hitMeshes(), false)
    for (const h of hits) {
      const e = h.object.userData.enemy
      if (!e || e.dead) continue
      return { enemy: e, zone: h.object.userData.zone || 'body', point: h.point, distance: h.distance, normal: h.face?.normal || new THREE.Vector3(0, 1, 0) }
    }
    return null
  }

  damage(e, amount, zone, point, dir) {
    if (e.dead) return { dead: false, damage: 0 }
    let dmg = amount
    if (zone === 'head') dmg *= e.cfg.sniper ? 2.2 : 2.4
    else if (zone === 'limb') dmg *= 0.72
    else if (zone === 'core') dmg *= 2.4
    e.health -= dmg
    e.hitFlash = 0.12
    e.suppressT = Math.max(e.suppressT, 0.35)
    this.effects.blood(point, dir, zone === 'head' ? 1.4 : 1)
    if (e.cfg.boss && zone === 'core') {
      for (let i = 0; i < 10; i++) {
        this.effects.sparks.spawn({
          pos: point.clone(), vel: new THREE.Vector3(rand(-4, 4), rand(0, 5), rand(-4, 4)),
          color: [1, 0.35, 0.15], size: rand(0.04, 0.1), life: rand(0.2, 0.5), gravity: 5, drag: 0.9,
        })
      }
    }
    // flinch
    e.aimTimer = Math.max(e.aimTimer, e.cfg.sniper ? 0.4 : 0.15)
    if (e.health <= 0) {
      this.kill(e, zone === 'head' || zone === 'core', dir)
      return { dead: true, damage: dmg, headshot: zone === 'head' || zone === 'core' }
    }
    return { dead: false, damage: dmg, headshot: zone === 'head' }
  }

  kill(e, headshot, dir) {
    e.dead = true
    e.alive = false
    e.deadT = 0
    e.deathSign = Math.random() > 0.5 ? 1 : -1
    e.laser.visible = false
    e.laser.material.opacity = 0
    if (e.cfg.boss) {
      // boss death spectacle
      this.effects.explosion(e.root.position.clone().setY(e.root.position.y + 1.4), { radius: 7 })
    }
    for (let i = 0; i < 14; i++) {
      this.effects.blood(new THREE.Vector3(e.root.position.x, e.root.position.y + rand(0.8, 1.6), e.root.position.z), new THREE.Vector3(rand(-1, 1), rand(0, 1), rand(-1, 1)), 1)
    }
    this.onKill?.(e, { headshot, dir })
  }

  spawnRocket(e, player) {
    const start = new THREE.Vector3()
    e.muzzle.getWorldPosition(start)
    const target = player.cameraPos.clone()
    const dir = target.sub(start).normalize()
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), new THREE.MeshStandardMaterial({ color: 0x1a0b06, emissive: 0xff4a15, emissiveIntensity: 4 }))
    mesh.position.copy(start)
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: spriteTexture('glow'), color: 0xff5a20, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }))
    glow.scale.set(0.9, 0.9, 1)
    mesh.add(glow)
    this.scene.add(mesh)
    this.projectiles.push({ mesh, vel: dir.multiplyScalar(15).add(new THREE.Vector3(0, 1.2, 0)), life: 6, trail: 0 })
    this.audio.enemyShot(8, 0, true)
  }

  update(dt, time, player) {
    this.losTimer -= dt
    const playerChest = this.tmp.set(player.pos.x, player.pos.y + (player.crouching ? 0.9 : 1.35), player.pos.z)
    const cameraPos = player.cameraPos

    for (const e of this.enemies) {
      if (e.dead) {
        e.deadT += dt
        e.body.rotation.z = damp(e.body.rotation.z, e.deathSign * 1.45, 4, dt)
        e.body.position.y = damp(e.body.position.y, -0.55, 3, dt)
        if (e.deadT > 2.6) {
          e.root.position.y -= dt * 0.65
          e.body.rotation.x = damp(e.body.rotation.x, -0.2, 2, dt)
        }
        if (e.deadT > 3.8 && !e.removed) {
          e.removed = true
          this.scene.remove(e.root)
          this.scene.remove(e.laser)
          e.laser.geometry.dispose(); e.laser.material.dispose()
          disposeGroup(e.root)
        }
        continue
      }

      e.spawnT += dt
      const scale = e.cfg.scale
      const grow = clamp(e.spawnT / 0.35, 0, 1)
      e.root.scale.setScalar(scale * (0.7 + grow * 0.3))
      if (e.spawnT < 0.35) continue

      e.hitFlash = Math.max(0, e.hitFlash - dt)
      e.suppressT = Math.max(0, e.suppressT - dt)
      e.muzzleGlow = Math.max(0, e.muzzleGlow - dt)
      e.fireTimer -= dt
      e.strafeTimer -= dt
      e.repoTimer -= dt
      e.rocketTimer -= dt

      const dx = player.pos.x - e.root.position.x
      const dz = player.pos.z - e.root.position.z
      const dist = Math.hypot(dx, dz)
      const dirToPlayer = this.tmp2.set(dx, 0, dz).normalize()

      // LOS, throttled
      e.losTimer -= dt
      if (e.losTimer <= 0) {
        e.losTimer = 0.18 + Math.random() * 0.08
        e.los = this.checkLOS(e, cameraPos, playerChest)
      }

      if (e.cfg.boss && e.rocketTimer <= 0 && e.los && dist > 7) {
        this.spawnRocket(e, player)
        e.rocketTimer = rand(7.5, 11)
        e.fireTimer = Math.max(e.fireTimer, 0.5)
      }

      // movement
      let moveDir = new THREE.Vector3()
      let speed = e.cfg.speed
      const minR = e.cfg.rangeMin, maxR = e.cfg.rangeMax
      if (e.cfg.rusher && dist < 6.5) {
        moveDir.copy(dirToPlayer).multiplyScalar(0.2)
        speed *= 0.35
        if (e.meleeTimer <= 0) {
          e.meleeTimer = 1.3
          if (dist < 2.1 && e.los) {
            this.onPlayerDamage?.(13, e.root.position.clone().setY(e.root.position.y + 1.2), e)
            this.effects.blood(playerChest.clone(), new THREE.Vector3(rand(-1, 1), 1, rand(-1, 1)), 0.5)
          }
        }
      } else if (e.coverTarget) {
        const cdx = e.coverTarget.x - e.root.position.x, cdz = e.coverTarget.z - e.root.position.z
        const cd = Math.hypot(cdx, cdz)
        if (cd < 0.6) { e.coverTarget = null }
        else { moveDir.set(cdx / cd, 0, cdz / cd); speed *= 1.25 }
      } else if (dist > maxR) {
        moveDir.copy(dirToPlayer)
        // slight flank bias
        moveDir.x += Math.cos(time * 0.4 + e.walkPhase) * 0.25
        moveDir.z += Math.sin(time * 0.4 + e.walkPhase) * 0.25
        moveDir.normalize()
      } else if (dist < minR) {
        moveDir.copy(dirToPlayer).multiplyScalar(-1)
        if (e.cfg.sniper) speed *= 1.2
      } else {
        const strafe = new THREE.Vector3(-dirToPlayer.z, 0, dirToPlayer.x).multiplyScalar(e.strafeDir)
        moveDir.copy(strafe).multiplyScalar(0.85).addScaledVector(dirToPlayer, Math.sin(time * 0.7 + e.walkPhase) * 0.2)
        moveDir.normalize()
      }
      if (e.strafeTimer <= 0) {
        e.strafeTimer = rand(1.4, 3.6)
        if (Math.random() > 0.35) e.strafeDir *= -1
      }
      if (e.repoTimer <= 0) {
        e.repoTimer = rand(3.5, 7)
        if (!e.cfg.boss && !e.cfg.heavy && Math.random() < 0.5) {
          let best = null, bestD = 12
          for (const c of this.world.coverPoints) {
            const d = c.distanceTo(e.root.position)
            if (d < bestD && d > 0.5) { best = c; bestD = d }
          }
          if (best && bestD < 9) e.coverTarget = best
        }
      }
      e.meleeTimer = Math.max(0, e.meleeTimer - dt)

      if (moveDir.lengthSq() > 0.001) {
        const moved = this.moveEnemy(e, moveDir, speed, dt)
        e.moveSpeed = damp(e.moveSpeed, moved ? speed : 0, 8, dt)
      } else e.moveSpeed = damp(e.moveSpeed, 0, 8, dt)

      // separation
      for (const o of this.enemies) {
        if (o === e || o.dead) continue
        const sx = e.root.position.x - o.root.position.x
        const sz = e.root.position.z - o.root.position.z
        const d = Math.hypot(sx, sz)
        const min = 1.0 + (e.cfg.scale + o.cfg.scale) * 0.25
        if (d > 0.001 && d < min) {
          const push = (min - d) * 0.5
          e.root.position.x += sx / d * push
          e.root.position.z += sz / d * push
        }
      }
      this.world.boundsClamp(e.root.position, 0.5)
      e.root.position.y = damp(e.root.position.y, this.world.groundHeightAt(e.root.position.x, e.root.position.z), 12, dt)

      // face player
      const targetYaw = Math.atan2(-dx, -dz)
      let delta = targetYaw - e.root.rotation.y
      while (delta > Math.PI) delta -= TAU
      while (delta < -Math.PI) delta += TAU
      e.root.rotation.y += delta * Math.min(1, dt * (e.aiming ? 7 : 4.5))

      // walk animation
      const moveAmt = clamp(e.moveSpeed / e.cfg.speed, 0, 1)
      e.walkPhase += dt * (4.5 + moveAmt * 5.5)
      const swing = Math.sin(e.walkPhase) * 0.65 * moveAmt
      e.legs[0].rotation.x = swing
      e.legs[1].rotation.x = -swing
      e.body.position.y = Math.abs(Math.sin(e.walkPhase)) * 0.035 * moveAmt + Math.sin(time * 1.6 + e.walkPhase) * 0.008
      if (e.arms) {
        e.arms[0].shoulder.rotation.x = -1.1 + Math.sin(e.walkPhase) * 0.05 * moveAmt
        e.arms[1].shoulder.rotation.x = -1.25 - Math.sin(e.walkPhase) * 0.04 * moveAmt
      }

      // shooting
      if (e.cfg.sniper) this.updateSniper(e, dt, player, playerChest, dist)
      else this.updateGunfire(e, dt, player, dist)

      // footstep audio
      if (e.moveSpeed > 1 && dist < 14 && Math.random() < dt * 3.5) this.audio.footstep(false)

      // core pulse
      if (e.cfg.boss && e.coreMesh) e.coreMesh.material.emissiveIntensity = 2.8 + Math.sin(time * 5) * 1.2
    }

    // projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i]
      p.life -= dt
      p.vel.y -= 4.5 * dt
      p.mesh.position.addScaledVector(p.vel, dt)
      p.trail -= dt
      if (p.trail <= 0) {
        p.trail = 0.03
        this.effects.smoke.spawn({
          pos: p.mesh.position.clone(), vel: new THREE.Vector3(rand(-0.15, 0.15), rand(0.05, 0.25), rand(-0.15, 0.15)),
          color: [0.25, 0.24, 0.23], size: 0.35, life: 0.8, gravity: -0.3, drag: 0.94, grow: 0.7, alpha: 0.4,
        })
      }
      const floor = this.world.groundHeightAt(p.mesh.position.x, p.mesh.position.z)
      let hit = p.mesh.position.y < floor + 0.2
      if (!hit) {
        for (const c of this.world.colliders) {
          if (p.mesh.position.x > c.minX && p.mesh.position.x < c.maxX && p.mesh.position.z > c.minZ && p.mesh.position.z < c.maxZ && p.mesh.position.y > c.minY && p.mesh.position.y < c.maxY) { hit = true; break }
        }
      }
      if (hit || p.life <= 0) {
        const pos = p.mesh.position.clone()
        this.effects.explosion(pos, { radius: 4.5 })
        this.audio.explosion(pos.distanceTo(player.pos), 0)
        const pd = pos.distanceTo(player.pos)
        if (pd < 5.2) {
          const dmg = 34 * (1 - pd / 6)
          this.onPlayerDamage?.(dmg, pos, null)
        }
        this.scene.remove(p.mesh)
        p.mesh.geometry.dispose(); p.mesh.material.dispose()
        this.projectiles.splice(i, 1)
      }
    }
    this.audio.setIntensity(clamp(this.aliveCount() / 8, 0, 1))
  }

  moveEnemy(e, dir, speed, dt) {
    const r = e.radius
    const pos = e.root.position
    const tryMove = (dx, dz) => {
      const nx = pos.x + dx, nz = pos.z + dz
      if (nx < -33.5 || nx > 33.5 || nz < -33.5 || nz > 33.5) return false
      const gh = this.world.groundHeightAt(nx, nz)
      if (gh - pos.y > 0.5) return false
      if (this.world.colliderAt(nx, nz, r, pos.y, 1.7)) return false
      pos.x = nx; pos.z = nz
      return true
    }
    const step = speed * dt
    if (tryMove(dir.x * step, dir.z * step)) return true
    const angles = [0.6, -0.6, 1.2, -1.2, 1.9, -1.9]
    for (const a of angles) {
      const c = Math.cos(a), s = Math.sin(a)
      const nx = dir.x * c - dir.z * s
      const nz = dir.x * s + dir.z * c
      if (tryMove(nx * step, nz * step)) return true
    }
    return false
  }

  checkLOS(e, cameraPos, playerChest) {
    const origin = new THREE.Vector3(e.root.position.x, e.root.position.y + 1.55 * e.cfg.scale, e.root.position.z)
    const dir = playerChest.clone().sub(origin)
    const dist = dir.length()
    dir.normalize()
    this.raycaster.set(origin, dir)
    this.raycaster.far = dist - 0.4
    const hits = this.raycaster.intersectObjects(this.world.raycastTargets, true)
    return hits.length === 0
  }

  updateGunfire(e, dt, player, dist) {
    if (!e.los) {
      e.burstLeft = 0
      e.aiming = false
      return
    }
    if (e.burstLeft > 0) {
      e.burstTimer -= dt
      if (e.burstTimer <= 0) {
        e.burstTimer = e.cfg.burstGap
        this.enemyFire(e, player, dist)
        e.burstLeft--
        if (e.burstLeft <= 0) e.fireTimer = rand(e.cfg.fireGap[0], e.cfg.fireGap[1])
      }
      return
    }
    if (e.fireTimer <= 0 && dist < 42) {
      e.aiming = true
      e.aimTimer += dt
      const windup = e.cfg.heavy ? 0.35 : 0.55
      if (e.aimTimer > windup) {
        e.burstLeft = Math.round(rand(e.cfg.burst[0], e.cfg.burst[1]))
        e.burstTimer = 0
        e.aimTimer = 0
        e.aiming = false
      }
    }
  }

  updateSniper(e, dt, player, playerChest, dist) {
    if (!e.los) {
      e.aiming = false
      e.aimTimer = 0
      e.laser.visible = false
      return
    }
    if (e.fireTimer <= 0) {
      e.aiming = true
      e.aimTimer += dt
      const start = new THREE.Vector3(); e.muzzle.getWorldPosition(start)
      const arr = e.laser.geometry.attributes.position.array
      arr[0] = start.x; arr[1] = start.y; arr[2] = start.z
      arr[3] = playerChest.x + rand(-0.05, 0.05); arr[4] = playerChest.y; arr[5] = playerChest.z + rand(-0.05, 0.05)
      e.laser.geometry.attributes.position.needsUpdate = true
      e.laser.visible = true
      e.laser.material.opacity = 0.25 + Math.min(0.7, e.aimTimer) * 0.6
      if (e.aimTimer > 1.15) {
        this.enemyFire(e, player, dist, true)
        e.aimTimer = 0
        e.fireTimer = rand(e.cfg.fireGap[0], e.cfg.fireGap[1])
        e.aiming = false
        e.laser.visible = false
      }
    }
  }

  enemyFire(e, player, dist, sniper = false) {
    const origin = new THREE.Vector3()
    e.muzzle.getWorldPosition(origin)
    const chest = player.cameraPos.clone().add(new THREE.Vector3(0, -0.25, 0))
    const target = chest.clone()
    const moving = player.speed > 3
    const accuracy = e.cfg.accuracy * (moving ? 0.65 : 1) * (player.crouching ? 0.85 : 1) * clamp(1.15 - dist / 55, 0.3, 1.15)
    const hit = Math.random() < accuracy
    if (!hit) {
      const off = new THREE.Vector3(rand(-1.6, 1.6), rand(-0.9, 1.4), rand(-1.6, 1.6))
      target.add(off)
    }
    const dir = target.clone().sub(origin).normalize()
    // do not shoot through walls
    this.raycaster.set(origin, dir)
    this.raycaster.far = origin.distanceTo(target)
    const wall = this.raycaster.intersectObjects(this.world.raycastTargets, true)
    const end = wall.length ? wall[0].point : target
    this.effects.tracer(origin, end, sniper ? 0xffdfb0 : 0xff8a55, sniper ? 0.85 : 0.55)
    this.effects.muzzleFlash(origin, dir, e.cfg.heavy ? 1.2 : 0.75)
    const pan = this.panFor(origin, player)
    this.audio.enemyShot(dist, pan, e.cfg.heavy)
    if (hit && !wall.length) {
      this.onPlayerDamage?.(sniper ? e.cfg.damage : e.cfg.damage * rand(0.8, 1.2), origin, e)
    }
  }

  panFor(pos, player) {
    const dx = pos.x - player.pos.x
    const dz = pos.z - player.pos.z
    // player's right vector from yaw
    const rx = Math.cos(player.yaw), rz = -Math.sin(player.yaw)
    const d = Math.hypot(dx, dz) || 1
    return clamp((dx * rx + dz * rz) / d, -1, 1) * 0.8
  }

  clearLasers() {
    for (const e of this.enemies) { e.laser.visible = false; e.laser.material.opacity = 0 }
  }

  clear() {
    for (const e of this.enemies) {
      this.scene.remove(e.root); this.scene.remove(e.laser)
      disposeGroup(e.root)
      e.laser.geometry.dispose(); e.laser.material.dispose()
    }
    this.enemies.length = 0
    for (const p of this.projectiles) { this.scene.remove(p.mesh); p.mesh.geometry.dispose(); p.mesh.material.dispose() }
    this.projectiles.length = 0
  }

  minimapData() {
    return this.enemies.filter(e => !e.dead).map(e => ({ x: e.root.position.x, z: e.root.position.z, alerted: e.alerted, boss: e.cfg.boss }))
  }
}

